/* Help texts per language. Body format: paragraphs separated by blank lines, "• " starts a bullet, "```" fences a code block,
   **text** is bold. Sections marked adminOnly appear for administrators only. Icons are resolved by key in help.jsx. */

const EX_CALL = '```\n{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"get_table","arguments":{"table":"gold.partners.loss_ratio"}}}\n```';
const EX_READ = '```\n{"jsonrpc":"2.0","id":2,"method":"resources/read","params":{"uri":"okf://hubs/health/index.md"}}\n```';
const EX_OKF = '```\n{"jsonrpc":"2.0","id":3,"method":"tools/call","params":{"name":"export_okf","arguments":{"hub":"Sales","format":"files"}}}\n```';

import { helpFr } from "./help-fr.js";
import { helpIt } from "./help-it.js";

export const HELP = {
  en: {
    title: "Help — feature guide",
    sub: "How the Alassio Data Catalog works, feature by feature. Roles: Admin > Data Steward (write/edit/import) > Guest (read-only).",
    sections: [
      { icon: "boxes", title: "Data hub types, data hubs & hierarchy", body: `The catalog is organised as Data Hub Type → Data Hub → Database → Schema → Table → Attribute. Data hub types (Finance, HR, Sales, SOURCE) group data hubs by business segment — SOURCE holds the generic source systems, exists from the first start and is always listed last in the tree, below a separator line; a data hub is a free-text group of databases inside a type, e.g. SALES_DE → BRONZE / SILVER / GOLD, with its BPO, an optional data domain and an optional link to LeanIX (shown on the data hub page, its card, the Governance Overview and the databases' Governance tab). Select a data hub type to see and create its data hubs; select a data hub to see and create its databases. Navigate via the tree or the cards; the breadcrumb always shows where you are.` },
      { icon: "search", title: "Search", body: `The search box finds objects across names, descriptions, business definitions, business terms, tags, data types and stewards, ranked by relevance. Narrow results with the facet filters (object type, hub, medallion layer, sensitivity). Clicking a result jumps straight to the object.` },
      { icon: "pencil", title: "Editing metadata", body: `Data Stewards and Admins create, edit and delete all objects. Every table carries technical metadata (attributes, data types, constraints, sensitivity) and business metadata (business definition, business terms, tags) on separate tabs.` },
      { icon: "shield", title: "Governance", body: `Databases belong to Data Domains; data hubs have a BPO, domains have an Owner and a Data Steward, tables can have their own steward. The Governance Overview manages assignments and people; each table's Governance tab shows the effective responsibilities and flags PII attributes.` },
      { icon: "lineage", title: "Data lineage", body: `Databases carry a medallion layer (bronze → silver → gold); their tables inherit it. The Lineage view shows only tables with lineage links; pick a data product (schema in a gold-layer database) to trace its whole feeding chain. Open the full lineage from the dashboard, from a data product page (pre-filtered) or from a table's Lineage tab. Clicking an upstream source, a downstream consumer or an arrow opens attribute mapping — optionally map the columns of the two tables onto each other. Links for Unity-Catalog-imported tables are locked — they are managed in Databricks and refreshed on import.` },
      { icon: "upload", title: "Import menu", body: `Bundles everything that brings metadata into the catalog. Entries appear only for roles that may use them.

• **Import CSV** (Stewards, Admins) — loads the catalog CSV format (one row per attribute). Headers are matched case-insensitively. Missing types, data hubs, databases, schemas, tables, attributes, domains and people are created automatically; existing objects are matched by name and enriched. The import runs on the server as a background job with a progress dialog (upload → parsing → writing), so files with hundreds of thousands of rows load in minutes while the browser stays responsive; above 5,000 attributes the catalog switches to lazy loading.
• **Unity Catalog** (Admins) — runs on the server since v1.66: pick a sync profile or enter a one-off connection (workspace URL, personal access token / service principal / app identity, optional SQL warehouse ID), connect, choose a catalog and the target type, data hub and layer; the import runs as a server job with a progress dialog and brings schemas, tables, columns, optional lineage and — with a warehouse — the governance tags. The token is used for this import only and never reaches the browser's storage; "Save as sync profile" keeps the connection for scheduled runs. Power BI, dbt and ODCS bundles are parsed and applied on the server too.
• **Load source** (Admins) — offers previously used sources for prefill (passwords are never stored) and introspects source systems live into the SOURCE type: DuckDB database files on the server (read-only), data lake files (Parquet/CSV/JSON/Delta/Iceberg on disk, S3 or Azure via DuckDB), MySQL/MariaDB, PostgreSQL, Microsoft SQL Server, Oracle, Snowflake, IBM DB2, SAP HANA via SQLAlchemy, any dialect via a SQLAlchemy URL, any database via the generic JDBC connector, SAP SuccessFactors and any OData v2/v4 service (SAP S/4HANA), Kafka Schema Registry (topics → tables) and Informatica Data Catalog via its API. Bundle imports load several databases plus lineage into a hub of your choice: Power BI (workspaces, datasets, reports via the admin Scanner API), dbt projects (manifest.json + catalog.json, lineage from depends_on) and ODCS data contracts (YAML/JSON). Credentials are used once and never stored; these sources have no write-back.` },
      { icon: "download", title: "Export menu", body: `Everything that takes metadata out of the catalog. Export CSV and Export OKF are available to all roles; the write-back is open to every role and writes your own changes. All three share the same selection dialog: tick whole types, databases, schemas or single tables.

• **Export CSV** — one row per attribute with all technical, business and governance columns; rendered and streamed by the server, so it works for any catalog size. The file re-imports 1:1 via Import CSV.
• **Export OKF** — an Open Knowledge Format v0.2 bundle as zip: Markdown files with YAML frontmatter, one concept per file, linked as a graph (index.md, hubs/…/index.md, …/<table>.md, people/, domains/, log.md). Made for AI agents, LLM wikis and knowledge bases — the same bundle is available to agents live via MCP.
• **Write back to UC** (all roles, v1.77) — opens a preview first: the catalog is compared with Unity Catalog and the dialog lists **your own** pending changes (descriptions, owners, stewards, domains, sensitivity, classification — attributed through the audit trail), how many changes belong to which other user, and what has no recorded author. Only your own changes are written — every user writes their own changes back; admins additionally write the ones without an author. Descriptions become comments, Sensitivity/Classification column tags, Data Owner / Data Steward / Data Domain catalog tags, layer and data hub catalog properties — only differences, nothing structural is ever created, altered or deleted in Databricks. The connection and credentials come from a sync profile (Admin › Backups & jobs); a profile's automatic write-back after each sync run remains an admin setting that writes all changes.` },
      { icon: "history", title: "Audit trail & versioning", body: `Every change to every record is logged with user, timestamp and field-level before/after. The Audit view shows the full trail; the History button on each object shows its versions, with one-click restore of previous versions or deleted records (Stewards and Admins).` },
      { icon: "key", title: "Your account & 2FA", body: `The key icon opens security settings where you can enable two-factor authentication by scanning a QR code with any TOTP authenticator app (or entering the key manually). New users are offered 2FA setup right after activating their account — it can also be skipped and enabled later. If Entra ID sign-in is enabled by an admin, you can sign in with your Microsoft work account; Entra's MFA replaces local 2FA on that path. After three failed sign-in attempts each further attempt is slowed down; after ten the account is locked for 15 minutes. **Password**: the same dialog lets you change your password (current password required; your other sessions are signed out). Forgot it? With e-mail configured the sign-in screen offers *Forgot your password?* and mails a 24-hour reset link; otherwise an admin issues one under Admin › Users. A reset ends every session of the account; 2FA stays enabled.` },
      { icon: "book", title: "Glossary", body: `The Glossary button lists all business terms with a search box. A glossary term is mainly a free-text definition; it can link to any number of catalog entities (clickable), carry named URLs to external resources and have files attached (max 15 MB each, downloadable by all roles). Stewards and Admins create, edit and delete terms; changes are audited. On tables and attributes the field Glossary term offers the names as suggestions; typing an unknown term creates it automatically.` },
      { icon: "store", title: "Marketplace & data product workflow", body: `• **Request access** (all roles): pick a data product, state the purpose, submit; Admins approve or reject and the requester is notified.
• **Design a new data product** (Project Managers, Admins): name, description, data hub type, the project (required) and the use case (required) — the selected SOURCE tables receive the Data Product, Project and Use Case tags as soon as the design is submitted; editing the selection adds or removes them, withdrawing or deleting the design removes them. The Advanced section takes refresh frequency, classification, historization, data type, the needed-by date and the retention (e.g. 3 months).

Selecting a request shows its three phases with their state and the recent history:

• **1 · Data Sourcing** — a submitted design goes to the Business Analyst / Req. Engineer automatically, who refines it (the analyst may edit the design entries), marks it Design refined and then documents the sourcing (source system, BPO, LeanIX link, data steward); Submit and request Approval sends it to the BPO directly. A View button shows all entries laid out like the input forms. The BPO approves the use of the data (attaching the confirming document) — the design goes to Data Ingestion automatically — or declines with a reason, which sends it back to the analyst. Data Ingestion confirms the ingested tables with their location, which forwards the design to the refinement automatically, or returns it.
• **2 · Data Product Refinement** — the Business Analyst refines the data product and completes the step with notes (e.g. where it is documented in Confluence) and optional file attachments; this forwards it to Development automatically, or the analyst returns it.
• **3 · Development & Test / Sign-off** — Data Product Development confirms Development (with notes on the result), UAT and SIT one after the other (or returns the design at any of them); then Data Product Development records the release to PRD and the Project Manager who submitted the design gives the final Sign-off — the finished data product then receives the Data Product, Project and Use Case tags; the source tables carry theirs since the design was submitted. Design refined, Refinement completed, Development, UAT, SIT and Released to PRD each open a dialog with required notes and optional file attachments. The expanded request shows every process step as a circle on the right: green = completed, grey = open, blue ring = current.

Every request shows its phase and whose action is awaited. Every step notifies the submitter and the next role. Admins can delete any request after a double confirmation. The BPMN process documentation is linked at the top of the Marketplace.` },
      { icon: "message", title: "Messages", body: `Messages are part of My Dashboard under "Waiting for my action" (the My Dashboard button carries the unread counter): workflow notifications, decisions on access requests and stewardship tasks. Messages link to the request list or the table concerned; with SMTP configured a copy goes by e-mail. Project Managers and Admins can use "Request business descriptions" on any table: the data steward receives a message; without a steward the data owner is asked to assign one; without an owner the Admins are asked to name one.` },
      { icon: "send", title: "Access requests (data products)", body: `Schemas in a gold-layer database are data products (e.g. Sales › SALES_DE › GOLD › partners). Each carries a Request access button that opens the Marketplace with the product pre-selected.` },
      { icon: "tag", title: "Project and Use Case tags", body: `Tables and data products carry the tags "Project" and "Use Case" with one or more values — set on the table or data product page by owners/stewards, or automatically from a data product design. They are searchable, exported in CSV/OKF and returned by MCP.` },
      { icon: "layers", title: "Discover Data Products (Project Managers, Admins)", body: `One page for the state of all data products, filterable by data domain, project and use case: finished ones (schemas in gold-layer databases and completed designs) and every planned or requested data product with its phase, exact status and whose feedback is awaited — sorted by data domain and data hub type. Rows open the schema or the request list.` },
      { icon: "users", title: "Language", body: `The interface is available in English, German, Polish, Spanish, French and Italian — switch it with the selector next to Sign out (or on the sign-in screen). The choice is stored with your account; notifications reach you in that language.` },
      { icon: "layers", title: "Large catalogs", body: `Above 5,000 attributes the catalog loads lazily: the tree, tables and dashboards arrive immediately with attribute counts, and a table's attributes are fetched when you open it. Exports and the write-back switch to the complete catalog automatically.` },
      { icon: "usercog", title: "My Dashboard", body: `Your personal view: your account roles and matching person record with your data domains; everything waiting for your action (workflow approvals and confirmations, access requests for your products, stewardship tasks and unread messages); requests and designs you initiated with their phase and next step; your glossary terms; and every data hub, database, schema and table that lists you as BPO, owner or steward.` },
      { icon: "shield", title: "Permissions — who may change what", body: `Account roles decide whether you may sign in and edit at all; responsibilities decide what. A person may hold several roles — permissions follow the highest one (Admin › Data Steward › Project Manager › Business Analyst / Data Ingestion / Development › Guest); workflow steps address every role held. Responsibilities are people-based: your account is matched to the people directory by e-mail (or exact name).

• **Inheritance**: ownership and stewardship flow downwards — data hub (BPO) → domain → database → schema → table — and can be overridden on every level. Data hub types have no owner. Data domains inherit downwards as well.
• **Admins**: invite users, change the structure, set BPOs and owners, restore history — everything.
• **Data owners**: set the data steward on their assets and everything below; edit tables and attributes like a steward.
• **Data stewards**: edit tables and attributes for which they are the effective steward, incl. creating tables in their schemas.
• **Lineage**: admins, or the owner/steward of one of the two tables. **Glossary**: admins, or anyone with at least one responsibility.
• **Guests** and the workflow roles Project Manager, Data Ingestion and Development: read everything, use the Marketplace and act in the workflow — no catalog edits.
• **Agents**: technical accounts for MCP clients, no governance role, created and deleted by Admins only; their keys (read or write scope) are the credential for POST /mcp.

Buttons you may not use are hidden; the server enforces the same rules on every save.` },
      { icon: "bot", title: "MCP server for AI agents", body: `The catalog is a Model Context Protocol server (Streamable HTTP, JSON-RPC 2.0) at POST /mcp. Agents — Claude, agent frameworks, IDE assistants — read, search and change the catalog with the same rules as the UI; user management is not exposed. Every agent change is audited under the agent's name.

**Connecting.** Use the URL https://<server>/mcp with the header Authorization: Bearer <key>, where the key is either the static MCP_TOKEN or an agent key issued in User management (Invite Agent). Clients that only speak stdio bridge with npx mcp-remote.

**Methods.** initialize, ping, tools/list, tools/call, resources/list, resources/read. Example:
${EX_CALL}
**References** are paths: database, database.schema, database.schema.table, database.schema.table.attribute (case-insensitive).

**Tools.** Read: get_overview, list_hubs, list_databases, list_schemas, list_tables, get_table, list_data_products, get_lineage, search_catalog, get_audit. Write: create/update/delete for hubs, databases, schemas, tables and attributes, add/remove lineage, map/unmap lineage attributes, export_okf. Read-scope keys are refused for mutating tools.` },
      { icon: "json", title: "OKF via MCP — how agents read the catalog", body: `The whole catalog is exposed as an Open Knowledge Format bundle in two ways:

• **Resources** (recommended for reading): resources/list returns every concept file as okf://<path>; resources/read returns its Markdown. Start at okf://index.md and follow the links downwards — progressive disclosure, an agent reads only what it needs.
${EX_READ}
• **Tool export_okf**: optional hub, database, schema, table restrict the bundle to a subtree; format files (default) or zip_base64.
${EX_OKF}
A concept file has YAML frontmatter (type, title, id, path, hub, data_hub, medallion_layer, data_product, steward, tags, provenance) and Markdown with description, business definition, governance, an attributes table and lineage sections. The same bundle is what Export → Export OKF downloads.` },
      { icon: "server", title: "Load generic data sources (admins)", body: `Admins introspect source systems live: DuckDB database files stored on the catalog server (native driver, read-only, incl. COMMENT ON texts and primary keys), MySQL/MariaDB, PostgreSQL, IBM DB2 and SAP HANA via SQLAlchemy (or any dialect via a SQLAlchemy URL), Microsoft SQL Server (pymssql), Oracle (oracledb thin) and Snowflake, data lake files with DuckDB (Parquet/CSV/JSON/Delta/Iceberg — local, S3/MinIO, Azure Data Lake; every path or glob becomes a table of type FILE), SAP SuccessFactors and any OData v2/v4 service via $metadata (entity types → tables, keys → primary keys, SAP labels → descriptions), Kafka Schema Registry (latest Avro/JSON Schema/Protobuf per subject → topics as tables of type TOPIC, nested records as dotted attributes, key schema as key.* primary keys), any other system via a generic JDBC connector, and Informatica Data Catalog via its Catalog Search API. Loaded databases are placed in the SOURCE type and have no write-back. Bundle sources go to a hub of your choice and bring lineage: Power BI (admin Scanner API — workspace → database, dataset → schema, tables with columns and measures, reports as objects of type REPORT in schema "Reports" with lineage dataset table → report), dbt (models/seeds/snapshots/sources → tables, documented columns with types from catalog.json, not_null/unique tests → nullability and keys, depends_on → lineage; existing tables are enriched rather than duplicated) and Open Data Contract Standard files (v3 schema/properties or v2 dataset/columns: classification → sensitivity, businessName → business term, primaryKey/required → key and nullability; contract, status, domain, data product and team in the business definition). Since v1.60 the API connectors (OData/SuccessFactors, Kafka Schema Registry, Power BI, Informatica) run inside the catalog server itself; only DuckDB, lake files, SQL dialects and JDBC need the optional Python inspector service. On installations without it (for example Databricks Apps) those entries are hidden and the dialog explains the alternative: register databases in Unity Catalog (Lakehouse Federation) and load them with the Unity Catalog sync.` },
      { icon: "shield", title: "Stewardship: certification, reviews, ownership attestation", body: `On a table's Governance tab the responsible owner or steward can **endorse** the table (trusted, reviewed — counts as a review), **deprecate** it with an optional successor table and a reason (consumers see the badge and the successor on the table, on the schema cards and in the dashboard), remove the certification, **mark it as reviewed** and set a **review cycle** (90/180/365 days). Owners **confirm ownership** on tables, schemas, databases and domains where they are set explicitly; the policy (Governance Overview, admins) says how often — default every 180 days. Due and overdue reviews and attestations appear under My Dashboard › Stewardship tasks with one-click actions, and once a day the responsible people get an in-app reminder (e-mail when SMTP is configured), at most every 7 days per object. Only the owner may attest; stewards review and certify. MCP agents use certify_table, review_table and list_stewardship_tasks.` },
      { icon: "server", title: "Backups & jobs (admins)", body: `Admin › Backups & jobs writes a gzip'd catalog dump to the server on a daily schedule (time and retention are configurable) and on demand — plus a full SQL dump of the whole database when mysqldump is installed. **Verify** runs a restore drill: the file is re-read, its structure and referential integrity are checked and the record counts are compared with the live catalog. **Restore** replays a backup through the normal restore job, downloads hand you the files. The page also lists the recent background jobs (imports, restores, backups) with their outcome; the list is stored in the database and survives service restarts — a job that was running during a restart is shown as interrupted.` },
      { icon: "message", title: "Collaboration: discussion, questions, ratings, usage", body: `Every table has a **Discussion** tab (data products show the discussion below their tables): anyone signed in can post comments, ask **questions** and answer them. A question notifies the effective data steward and owner (in-app, e-mail with SMTP) in their language; an answer notifies the asker; the asker, stewards and admins mark a question **resolved**. Open questions addressed to you — and your own — are listed under My Dashboard › Questions. Tables and data products carry a **star rating** (1–5, one vote per person, average shown in the header). The catalog also records **usage**: views (one per person and object per ten minutes), search terms and exports. A table's usage line sits on its Governance and Discussion tabs; the dashboard's Usage panel shows the most viewed tables, the top search terms and the best rated tables for 7 to 365 days. MCP agents use get_discussion, list_open_questions and add_comment; get_table includes rating, open questions and usage.` },
      { icon: "key", title: "OAuth 2.1 for MCP clients", body: `Besides agent keys, MCP clients (Claude, IDE assistants, agent frameworks) can connect **as you** through OAuth 2.1: the client discovers /.well-known/oauth-protected-resource and /.well-known/oauth-authorization-server, registers itself dynamically (RFC 7591), sends you to a consent page (sign in first if needed), and receives an access token with PKCE (S256, mandatory). Tokens are opaque, expire after an hour and are refreshed with rotating refresh tokens (30 days); the scope catalog:write is granted only to Admins and Data Stewards — everyone else gets catalog:read. Every change is audited under your name. The key icon › **Connected MCP applications** lists your connections and lets you disconnect one (all its tokens die immediately); Admins see every connection under Users. Each credential — OAuth token, agent key or static token — is rate limited (default 300 requests and 60 write calls per minute; HTTP 429 with Retry-After).` },
      { icon: "key", title: "Identity: SSO enforcement, group → role mapping, proxy sign-in", body: `Admins can **enforce SSO**: everyone signs in through Entra ID, password sign-in stays available only for the listed **break-glass accounts** (your own account is added when the list is empty) — the sign-in screen then shows the Microsoft button and a small "Break-glass sign-in" link. The **group → role mapping** (Admin › Users) derives catalog roles from identity-provider groups: Entra's groups claim (object ids or names) and app roles, or — in header mode — the proxy's groups header or the Databricks account groups. Rules decide the roles of newly provisioned accounts; with "roles follow groups" they are re-applied on every sign-in, and unmatched users get the default roles or are denied. The last admin is never demoted. In **header mode** (AUTH_MODE=header, e.g. as a Databricks App or behind oauth2-proxy) the catalog trusts the identity headers of the authenticating proxy, creates accounts on first sight (AUTH_BOOTSTRAP_ADMINS become admins) and shows no login form; a shared secret header protects the Node port. MCP keys and tokens are unaffected.` },
      { icon: "server", title: "Operations: database engines, backup storage, health, external scheduler", body: `The server runs on **MariaDB (default) or PostgreSQL / Databricks Lakebase** (DB_DRIVER=postgres; same SQL in the code, translated DDL, tsvector full-text search, pg_dump backups; Lakebase credentials are fetched per connection with DB_PASSWORD_PROVIDER=databricks). Backups go to a **local directory, an S3-compatible bucket, an Azure Blob container or a Unity Catalog Volume** (BACKUP_STORAGE=local|s3|azure|databricks); restore, restore drills and downloads read from the same storage. **GET /healthz** reports readiness (database, catalog version, live jobs, memory) for monitors and platform health checks. The scheduled tasks — backup, stewardship reminders, usage purge, Unity Catalog sync — can be run on demand with **POST /admin/tasks/<name>/run** (admin session or the TASKS_TOKEN bearer); with SCHEDULER=external the in-process timers are off and a platform scheduler (cron, Databricks Job) drives them. SIGTERM shuts the service down gracefully within 15 seconds: running jobs are marked interrupted, the pool is closed. Dump export, backups, CSV/OKF exports and the CSV import stream attributes table by table, so even 400,000 attributes never sit in memory at once.` },
      { icon: "upload", title: "Scheduled Unity Catalog synchronisation", body: `Admin › Backups & jobs › **Scheduled synchronisation**: a sync profile names a Databricks workspace, a Unity Catalog catalog, the target data hub type / data hub / layer, the authentication (personal access token, a service principal, or the app's own identity on Databricks Apps), a schedule (manual, hourly, daily at a time) and a mode. **Report only** records the drift — new schemas, tables and columns, removed tables and columns, changed column types — and notifies the responsible stewards and owners in their language (admins when nobody is responsible); **Apply** additionally imports new objects, updates column types and, when enabled, deletes tables and columns that disappeared from Unity Catalog (lineage optional). Every run is audited; the last result with samples is shown on the profile. "Test connection" counts schemas, tables and columns without touching the catalog; "Run now" ignores the schedule. **Write-back (v1.64):** a profile can also push catalog metadata back to Unity Catalog after each run or on demand — descriptions as comments, Data Owner / Data Steward / Data Domain / Sensitivity / Classification as UC tags, data hub / layer / country as catalog properties; only differences, nothing is created or deleted, no browser needed. Enable it in the profile, enter the SQL warehouse ID for tags and column comments, preview with the cloud button, run with "Write back"; the result is shown under the profile and audited. Without a warehouse ID the changes that need SQL (column comments, table properties, tags) are counted as skipped — comments and catalog properties are still written and the run does not fail. **v1.66:** the SQL warehouse ID is a profile setting used for both directions — governance tags (Sensitivity, Classification, Data Owner / Steward / Domain) are read on import when "Import governance tags" is on, and tags and column comments are written on write-back. The one-off import from the Import menu uses the same engine and can be saved as a profile.` },
      { icon: "boxes", title: "Dashboard", body: `The homepage shows catalog KPIs: data hub types and objects, data products, distinct owners and stewards, and governance coverage — the percentage of databases with owner, tables with data steward, and data products with owner and steward. Since v1.66 the attribute coverage KPIs (tables and attributes with description, attributes with sensitivity and business term) are computed on the server (/api/stats), so they are exact for large catalogs that load lazily.` },
      { icon: "shield", adminOnly: true, title: "Admin menu (Admins only)", body: `• **Users** — invite people by e-mail with roles (multi-select; without SMTP the invitation link is shown to copy), edit name, e-mail and roles, see 2FA/Entra status, delete accounts; create Agents by name with an MCP key and a read/write scope; configure Entra ID sign-in. The last admin cannot be demoted or deleted. Invitation links are shown once (tokens are stored hashed) — *Renew* issues a new link, *Withdraw* cancels an invitation. The circular-arrow button next to a password account issues a **password-reset link** (24 hours, single use, mailed when SMTP is configured).
• **Governance Overview** — assign the BPO per data hub and owners/stewards to data domains, see who holds the workflow roles, maintain the people directory.
• **Audit trail** — the full change log across the catalog.
• **Dump / Restore** — download the complete catalog as JSON (backup) and replace it from a dump; restores are audited, accounts are not touched.
• **Backups & jobs** — scheduled backups, restore drills, job history.
• **Export Glossary Terms** — all terms as JSON (attachments as references).` },
    ],
  },
  de: {
    title: "Hilfe — Funktionsübersicht",
    sub: "So funktioniert der Alassio Data Catalog, Funktion für Funktion. Rollen: Admin > Data Steward (schreiben/bearbeiten/importieren) > Gast (nur lesen).",
    sections: [
      { icon: "boxes", title: "Data Hub Types, Data Hubs & Hierarchie", body: `Der Katalog ist gegliedert in Data Hub Type → Data Hub → Datenbank → Schema → Tabelle → Attribut. Data Hub Types (Finance, HR, Sales, SOURCE) bündeln Data Hubs nach Geschäftssegment — SOURCE nimmt die generischen Quellsysteme auf, existiert ab dem ersten Start und steht im Baum immer zuletzt, durch eine Linie abgesetzt; ein Data Hub ist eine Freitext-Gruppe von Datenbanken innerhalb eines Types, z. B. SALES_DE → BRONZE / SILVER / GOLD, mit BPO, optionaler Datendomäne und optionalem LeanIX-Link (sichtbar auf der Data-Hub-Seite, der Karte, in der Governance Overview und im Governance-Tab der Datenbanken). Wähle einen Type, um seine Data Hubs zu sehen und anzulegen; wähle einen Data Hub, um seine Datenbanken zu sehen und anzulegen. Navigiere über den Baum oder die Karten; die Breadcrumb zeigt immer, wo du bist.` },
      { icon: "search", title: "Suche", body: `Das Suchfeld findet Objekte über Namen, Beschreibungen, fachliche Definitionen, Glossarbegriffe, Tags, Datentypen und Stewards, nach Relevanz sortiert. Mit den Facettenfiltern (Objekttyp, Hub, Medallion-Layer, Sensitivität) grenzt du ein. Ein Klick auf ein Ergebnis springt direkt zum Objekt.` },
      { icon: "pencil", title: "Metadaten bearbeiten", body: `Data Stewards und Admins legen alle Objekte an, bearbeiten und löschen sie. Jede Tabelle trägt technische Metadaten (Attribute, Datentypen, Constraints, Sensitivität) und fachliche Metadaten (fachliche Definition, Glossarbegriffe, Tags) auf getrennten Tabs.` },
      { icon: "shield", title: "Governance", body: `Datenbanken gehören zu Datendomänen; Data Hubs haben einen BPO, Domänen einen Owner und einen Data Steward, Tabellen können einen eigenen Steward haben. Die Governance Overview verwaltet Zuordnungen und Personen; der Governance-Tab jeder Tabelle zeigt die effektiven Verantwortlichkeiten und markiert PII-Attribute.` },
      { icon: "lineage", title: "Data Lineage", body: `Datenbanken tragen einen Medallion-Layer (bronze → silver → gold); ihre Tabellen erben ihn. Die Lineage-Ansicht zeigt nur Tabellen mit Lineage-Verbindungen; wähle ein Datenprodukt (Schema in einer Gold-Datenbank), um seine gesamte Zulieferkette zu verfolgen. Die Gesamt-Lineage öffnest du vom Dashboard, von einer Datenproduktseite (vorgefiltert) oder vom Lineage-Tab einer Tabelle. Ein Klick auf eine Quelle, einen Konsumenten oder einen Pfeil öffnet das Attribut-Mapping — optional ordnest du die Spalten der beiden Tabellen einander zu. Verbindungen aus Unity Catalog importierter Tabellen sind gesperrt — sie werden in Databricks gepflegt und beim Import aktualisiert.` },
      { icon: "upload", title: "Import-Menü", body: `Bündelt alles, was Metadaten in den Katalog bringt. Einträge erscheinen nur für Rollen, die sie nutzen dürfen.

• **CSV importieren** (Stewards, Admins) — lädt das Katalog-CSV-Format (eine Zeile pro Attribut). Spaltenköpfe werden unabhängig von Groß-/Kleinschreibung erkannt. Fehlende Types, Data Hubs, Datenbanken, Schemata, Tabellen, Attribute, Domänen und Personen werden automatisch angelegt; vorhandene Objekte werden per Name gefunden und ergänzt. Der Import läuft als Hintergrundjob auf dem Server mit Fortschrittsdialog (Hochladen → Lesen → Schreiben); Dateien mit Hunderttausenden Zeilen laden in Minuten, der Browser bleibt bedienbar; ab 5.000 Attributen schaltet der Katalog auf Lazy Loading um.
• **Unity Catalog** (Admins) — läuft seit v1.66 auf dem Server: Sync-Profil wählen oder einmalige Verbindung eingeben (Workspace-URL, persönliches Zugriffstoken / Service Principal / App-Identität, optional SQL-Warehouse-ID), verbinden, Katalog sowie Ziel-Type, Data Hub und Layer wählen; der Import läuft als Server-Job mit Fortschrittsdialog und bringt Schemata, Tabellen, Spalten, optional Lineage und — mit Warehouse — die Governance-Tags mit. Das Token wird nur für diesen Import genutzt und landet nie im Browser; „Als Sync-Profil speichern“ behält die Verbindung für geplante Läufe. Auch Power-BI-, dbt- und ODCS-Bundles werden auf dem Server geparst und angewendet.
• **Quelle laden** (Admins) — bietet zuvor verwendete Quellen zum Vorbelegen an (Passwörter werden nie gespeichert) und liest Quellsysteme live in den SOURCE-Type: DuckDB-Datenbankdateien auf dem Server (nur lesend), Data-Lake-Dateien (Parquet/CSV/JSON/Delta/Iceberg lokal, auf S3 oder Azure über DuckDB), MySQL/MariaDB, PostgreSQL, Microsoft SQL Server, Oracle, Snowflake, IBM DB2, SAP HANA über SQLAlchemy, jeder Dialekt über eine SQLAlchemy-URL, jede Datenbank über den generischen JDBC-Konnektor, SAP SuccessFactors und beliebige OData-v2/v4-Services (SAP S/4HANA), Kafka Schema Registry (Topics → Tabellen) und Informatica Data Catalog über dessen API. Bündel-Importe laden mehrere Datenbanken samt Lineage in einen wählbaren Hub: Power BI (Workspaces, Datasets, Reports über die Admin-Scanner-API), dbt-Projekte (manifest.json + catalog.json, Lineage aus depends_on) und ODCS-Datenverträge (YAML/JSON). Zugangsdaten werden einmal verwendet und nie gespeichert; diese Quellen haben kein Write-back.` },
      { icon: "download", title: "Export-Menü", body: `Alles, was Metadaten aus dem Katalog herausführt. CSV- und OKF-Export stehen allen Rollen offen; das Write-back steht jeder Rolle offen und schreibt die eigenen Änderungen. Alle drei teilen denselben Auswahldialog: ganze Types, Datenbanken, Schemata oder einzelne Tabellen ankreuzen.

• **CSV exportieren** — eine Zeile pro Attribut mit allen technischen, fachlichen und Governance-Spalten; wird vom Server erzeugt und gestreamt, funktioniert daher bei jeder Kataloggröße. Die Datei lässt sich 1:1 über CSV importieren wieder einlesen.
• **OKF exportieren** — ein Open-Knowledge-Format-Bundle (v0.2) als Zip: Markdown-Dateien mit YAML-Frontmatter, ein Konzept pro Datei, als Graph verlinkt (index.md, hubs/…/index.md, …/<tabelle>.md, people/, domains/, log.md). Gemacht für KI-Agenten, LLM-Wikis und Wissensdatenbanken — dasselbe Bundle steht Agenten live über MCP zur Verfügung.
• **Nach UC zurückschreiben** (alle Rollen, v1.77) — öffnet zuerst eine Vorschau: der Katalog wird mit Unity Catalog verglichen, und der Dialog listet **deine eigenen** offenen Änderungen (Beschreibungen, Owner, Stewards, Domänen, Sensitivität, Klassifizierung — über den Audit-Trail zugeordnet), wie viele Änderungen welchem anderen Benutzer gehören und was keinen erfassten Autor hat. Geschrieben werden nur deine eigenen Änderungen — jeder Benutzer schreibt seine Änderungen selbst zurück; Admins schreiben zusätzlich die ohne Autor. Beschreibungen werden Kommentare, Sensitivität/Klassifizierung Spalten-Tags, Data Owner / Data Steward / Data Domain Katalog-Tags, Layer und Data Hub Katalog-Properties — nur Abweichungen, strukturell wird in Databricks nie etwas angelegt, geändert oder gelöscht. Verbindung und Zugangsdaten kommen aus einem Sync-Profil (Admin › Backups & Jobs); das automatische Write-back eines Profils nach jedem Sync-Lauf bleibt eine Admin-Einstellung, die alle Änderungen schreibt.` },
      { icon: "history", title: "Audit-Trail & Versionierung", body: `Jede Änderung an jedem Datensatz wird mit Benutzer, Zeitstempel und Feldwerten vorher/nachher protokolliert. Die Audit-Ansicht zeigt den kompletten Verlauf; der Historie-Button jedes Objekts zeigt dessen Versionen — mit Wiederherstellung früherer Versionen oder gelöschter Datensätze per Klick (Stewards und Admins).` },
      { icon: "key", title: "Dein Konto & 2FA", body: `Das Schlüsselsymbol öffnet die Sicherheitseinstellungen: Aktiviere die Zwei-Faktor-Authentifizierung, indem du einen QR-Code mit einer TOTP-Authenticator-App scannst (oder den Schlüssel manuell eingibst). Neuen Benutzern wird 2FA direkt nach der Kontoaktivierung angeboten — es lässt sich auch überspringen und später aktivieren. Hat ein Admin die Entra-ID-Anmeldung aktiviert, kannst du dich mit deinem Microsoft-Arbeitskonto anmelden; die MFA von Entra ersetzt dort die lokale 2FA. Nach drei Fehlversuchen wird jede weitere Anmeldung verlangsamt; nach zehn ist das Konto 15 Minuten gesperrt. **Passwort**: Im selben Dialog änderst du dein Passwort (aktuelles Passwort nötig; deine anderen Sitzungen werden abgemeldet). Vergessen? Ist E-Mail konfiguriert, bietet die Anmeldeseite *Passwort vergessen?* und schickt einen 24 Stunden gültigen Reset-Link; sonst stellt ein Admin unter Admin › Benutzer einen aus. Ein Reset beendet alle Sitzungen des Kontos; 2FA bleibt aktiv.` },
      { icon: "book", title: "Glossar", body: `Der Glossar-Button listet alle Fachbegriffe mit Suchfeld. Ein Glossarbegriff ist vor allem eine Freitext-Definition; er kann beliebig viele Katalogobjekte verknüpfen (anklickbar), benannte URLs auf externe Ressourcen tragen und Dateien anhängen (max. 15 MB je Datei, für alle Rollen herunterladbar). Stewards und Admins legen Begriffe an, bearbeiten und löschen sie; Änderungen werden auditiert. An Tabellen und Attributen schlägt das Feld Glossarbegriff die Namen vor; ein unbekannter Begriff wird automatisch angelegt.` },
      { icon: "store", title: "Marktplatz & Datenprodukt-Workflow", body: `• **Zugriff anfordern** (alle Rollen): Datenprodukt wählen, Zweck angeben, absenden; Admins genehmigen oder lehnen ab, der Anfragende wird benachrichtigt.
• **Neues Datenprodukt designen** (Projektmanager, Admins): Name, Beschreibung, Data Hub Type, das Projekt (Pflicht) und der Use Case (Pflicht) — die gewählten SOURCE-Tabellen erhalten beim Einreichen die Tags Data Product, Project und Use Case; beim Editieren der Auswahl werden sie ergänzt oder entfernt, beim Zurückziehen oder Löschen des Designs entfernt. Der Bereich „Advanced" nimmt Aktualisierungsfrequenz, Klassifizierung, Historisierung, Datentyp, den Bedarfstermin und die Aufbewahrung (z. B. 3 Monate) auf.

Die Auswahl eines Requests zeigt seine drei Phasen mit Status und der jüngsten Historie:

• **1 · Data Sourcing** — ein eingereichtes Design geht automatisch an den Business Analyst / Req. Engineer, der es verfeinert (die Design-Einträge darf er bearbeiten), mit „Design verfeinert“ bestätigt und dann das Sourcing dokumentiert (Quellsystem, BPO, LeanIX-Link, Data Steward); „Absenden und Freigabe anfordern“ schickt es direkt an den BPO. Ein „Ansehen“-Button zeigt alle Einträge im Layout der Eingabemasken. Der BPO gibt die Datennutzung frei (mit dem bestätigenden Dokument) — das Design geht automatisch an Data Ingestion — oder lehnt mit Begründung ab, was es an den Analysten zurückgibt. Data Ingestion bestätigt die ingestierten Tabellen mit ihrem Ort, was das Design automatisch ins Refinement weiterleitet, oder gibt es zurück.
• **2 · Datenprodukt-Refinement** — der Business Analyst verfeinert das Datenprodukt und schließt den Schritt mit Notizen (z. B. wo es in Confluence dokumentiert ist) und optionalen Dateianhängen ab; das leitet es automatisch an die Entwicklung weiter, oder der Analyst gibt es zurück.
• **3 · Entwicklung & Test / Abnahme** — die Datenprodukt-Entwicklung bestätigt nacheinander Entwicklung (mit Notizen zum Ergebnis), UAT und SIT (oder gibt das Design an jedem dieser Schritte zurück); danach dokumentiert die Datenprodukt-Entwicklung den Release nach PRD, und der Projektmanager, der das Design eingereicht hat, gibt das abschließende Sign-off — das fertige Datenprodukt erhält dann die Tags Data Product, Project und Use Case; die Quelltabellen tragen ihre Tags seit dem Einreichen des Designs. „Design verfeinert“, „Refinement abgeschlossen“, Entwicklung, UAT, SIT und „Released to PRD“ öffnen jeweils eine Maske mit Pflicht-Notizen und optionalen Dateianhängen. Der aufgeklappte Request zeigt rechts jeden Prozessschritt als Kreis: grün = abgeschlossen, grau = offen, blauer Ring = aktuell.

Jeder Request zeigt seine Phase und wessen Aktion aussteht. Jeder Schritt benachrichtigt den Einreicher und die nächste Rolle. Admins können jeden Request nach doppelter Bestätigung löschen. Die BPMN-Prozessdokumentation ist oben im Marktplatz verlinkt.` },
      { icon: "message", title: "Nachrichten", body: `Nachrichten sind Teil von „Mein Dashboard" unter „Wartet auf mich" (der Dashboard-Button trägt den Ungelesen-Zähler): Workflow-Benachrichtigungen, Entscheidungen zu Zugriffsanfragen und Steward-Aufgaben. Nachrichten verlinken auf die Request-Liste oder die betroffene Tabelle; bei konfiguriertem SMTP geht eine Kopie per E-Mail. Projektmanager und Admins können auf jeder Tabelle „Fachliche Beschreibungen anfordern": Der Data Steward erhält eine Nachricht; ohne Steward wird der Data Owner gebeten, einen zu benennen; ohne Owner werden die Admins gebeten, einen Owner zu benennen.` },
      { icon: "send", title: "Zugriffsanfragen (Datenprodukte)", body: `Schemata in einer Gold-Datenbank sind Datenprodukte (z. B. Sales › SALES_DE › GOLD › partners). Jedes trägt einen Button „Zugriff anfordern", der den Marktplatz mit vorgewähltem Produkt öffnet.` },
      { icon: "tag", title: "Project- und Use-Case-Tags", body: `Tabellen und Datenprodukte tragen die Tags „Project" und „Use Case" mit einem oder mehreren Werten — gesetzt auf der Tabellen- oder Produktseite durch Owner/Stewards oder automatisch aus einem Datenprodukt-Design. Sie sind durchsuchbar, werden in CSV/OKF exportiert und von MCP geliefert.` },
      { icon: "layers", title: "Datenprodukte entdecken (Projektmanager, Admins)", body: `Eine Seite für den Stand aller Datenprodukte, filterbar nach Datendomäne, Projekt und Use Case: fertige (Schemata in Gold-Datenbanken und abgeschlossene Designs) und jedes geplante oder angeforderte Datenprodukt mit Phase, genauem Status und ausstehender Rückmeldung — sortiert nach Datendomäne und Data Hub Type. Zeilen öffnen das Schema oder die Request-Liste.` },
      { icon: "users", title: "Sprache", body: `Die Oberfläche gibt es auf Englisch, Deutsch, Polnisch, Spanisch, Französisch und Italienisch — umschalten über den Wähler neben Abmelden (oder auf dem Anmeldebildschirm). Die Wahl wird mit Ihrem Konto gespeichert; Benachrichtigungen erreichen Sie in dieser Sprache.` },
      { icon: "layers", title: "Große Kataloge", body: `Ab 5.000 Attributen lädt der Katalog verzögert: Baum, Tabellen und Dashboards erscheinen sofort mit Attributzählern, die Attribute einer Tabelle werden beim Öffnen nachgeladen. Exporte und Write-back holen automatisch den vollständigen Katalog.` },
      { icon: "usercog", title: "Mein Dashboard", body: `Deine persönliche Sicht: deine Kontorollen und der passende Personendatensatz mit deinen Datendomänen; alles, was auf deine Aktion wartet (Freigaben und Bestätigungen im Workflow, Zugriffsanfragen zu deinen Produkten, Steward-Aufgaben und ungelesene Nachrichten); von dir gestartete Anfragen und Designs mit Phase und nächstem Schritt; deine Glossarbegriffe; und jeder Data Hub, jede Datenbank, jedes Schema und jede Tabelle, die dich als BPO, Owner oder Steward führt.` },
      { icon: "shield", title: "Berechtigungen — wer darf was ändern", body: `Kontorollen entscheiden, ob du dich anmelden und überhaupt bearbeiten darfst; Verantwortlichkeiten entscheiden, was. Eine Person kann mehrere Rollen haben — Berechtigungen folgen der höchsten (Admin › Data Steward › Projektmanager › Business Analyst / Data Ingestion / Entwicklung › Gast); Workflow-Schritte adressieren jede gehaltene Rolle. Verantwortlichkeiten sind personenbezogen: Dein Konto wird über die E-Mail (oder den exakten Namen) dem Personenverzeichnis zugeordnet.

• **Vererbung**: Ownership und Stewardship fließen nach unten — Data Hub (BPO) → Domäne → Datenbank → Schema → Tabelle — und lassen sich auf jeder Ebene übersteuern. Data Hub Types haben keinen Owner. Datendomänen vererben sich ebenfalls.
• **Admins**: Benutzer einladen, Struktur ändern, BPOs und Owner setzen, Historie wiederherstellen — alles.
• **Data Owner**: setzen den Data Steward auf ihren Assets und allem darunter; bearbeiten Tabellen und Attribute wie ein Steward.
• **Data Stewards**: bearbeiten Tabellen und Attribute, für die sie effektiver Steward sind, inkl. Anlegen von Tabellen in ihren Schemata.
• **Lineage**: Admins oder Owner/Steward einer der beiden Tabellen. **Glossar**: Admins oder jeder mit mindestens einer Verantwortung.
• **Gäste** und die Workflow-Rollen Projektmanager, Data Ingestion und Entwicklung: alles lesen, Marktplatz nutzen und im Workflow handeln — keine Katalog-Änderungen.
• **Agents**: technische Konten für MCP-Clients, keine Governance-Rolle, nur von Admins angelegt und gelöscht; ihre Schlüssel (Scope lesen oder schreiben) sind das Credential für POST /mcp.

Buttons, die du nicht nutzen darfst, sind ausgeblendet; der Server erzwingt dieselben Regeln bei jedem Speichern.` },
      { icon: "bot", title: "MCP-Server für KI-Agenten", body: `Der Katalog ist ein Model-Context-Protocol-Server (Streamable HTTP, JSON-RPC 2.0) unter POST /mcp. Agenten — Claude, Agent-Frameworks, IDE-Assistenten — lesen, durchsuchen und ändern den Katalog nach denselben Regeln wie die Oberfläche; die Benutzerverwaltung ist nicht erreichbar. Jede Agenten-Änderung wird unter dem Namen des Agents auditiert.

**Verbinden.** URL https://<server>/mcp mit dem Header Authorization: Bearer <key>; der Key ist entweder der statische MCP_TOKEN oder ein Agent-Schlüssel aus der Benutzerverwaltung (Agent einladen). Clients, die nur stdio sprechen, nutzen npx mcp-remote als Brücke.

**Methoden.** initialize, ping, tools/list, tools/call, resources/list, resources/read. Beispiel:
${EX_CALL}
**Referenzen** sind Pfade: datenbank, datenbank.schema, datenbank.schema.tabelle, datenbank.schema.tabelle.attribut (Groß-/Kleinschreibung egal).

**Tools.** Lesen: get_overview, list_hubs, list_databases, list_schemas, list_tables, get_table, list_data_products, get_lineage, search_catalog, get_audit. Schreiben: create/update/delete für Hubs, Datenbanken, Schemata, Tabellen und Attribute, add/remove lineage, map/unmap lineage attributes, export_okf. Schlüssel mit Scope „lesen" werden bei schreibenden Tools abgewiesen.` },
      { icon: "json", title: "OKF über MCP — wie Agenten den Katalog lesen", body: `Der gesamte Katalog ist auf zwei Wegen als Open-Knowledge-Format-Bundle erreichbar:

• **Ressourcen** (empfohlen zum Lesen): resources/list liefert jede Konzeptdatei als okf://<pfad>; resources/read liefert ihr Markdown. Starte bei okf://index.md und folge den Links nach unten — ein Agent liest nur, was er braucht.
${EX_READ}
• **Tool export_okf**: optionale Parameter hub, database, schema, table beschränken das Bundle auf einen Teilbaum; format files (Standard) oder zip_base64.
${EX_OKF}
Eine Konzeptdatei hat YAML-Frontmatter (type, title, id, path, hub, data_hub, medallion_layer, data_product, steward, tags, provenance) und Markdown mit Beschreibung, fachlicher Definition, Governance, Attributtabelle und Lineage-Abschnitten. Dasselbe Bundle lädt Export → OKF exportieren herunter.` },
      { icon: "server", title: "Generische Datenquellen laden (Admins)", body: `Admins lesen Quellsysteme live: DuckDB-Datenbankdateien auf dem Katalogserver (nativer Treiber, nur lesend, inkl. COMMENT-ON-Texten und Primärschlüsseln), MySQL/MariaDB, PostgreSQL, IBM DB2 und SAP HANA über SQLAlchemy (oder jeder Dialekt über eine SQLAlchemy-URL), Microsoft SQL Server (pymssql), Oracle (oracledb thin) und Snowflake, Data-Lake-Dateien mit DuckDB (Parquet/CSV/JSON/Delta/Iceberg — lokal, S3/MinIO, Azure Data Lake; jeder Pfad oder Glob wird eine Tabelle vom Typ FILE), SAP SuccessFactors und beliebige OData-v2/v4-Services über $metadata (Entitätstypen → Tabellen, Schlüssel → Primärschlüssel, SAP-Labels → Beschreibungen), Kafka Schema Registry (jeweils neuestes Avro-/JSON-Schema/Protobuf pro Subject → Topics als Tabellen vom Typ TOPIC, verschachtelte Records als punktierte Attribute, Key-Schema als key.*-Primärschlüssel), jedes andere System über den generischen JDBC-Konnektor und Informatica Data Catalog über dessen Catalog Search API. Geladene Datenbanken landen im SOURCE-Type und haben kein Write-back. Bündel-Quellen gehen in einen wählbaren Hub und bringen Lineage mit: Power BI (Admin-Scanner-API — Workspace → Datenbank, Dataset → Schema, Tabellen mit Spalten und Measures, Reports als Objekte vom Typ REPORT im Schema „Reports“ mit Lineage Dataset-Tabelle → Report), dbt (Models/Seeds/Snapshots/Sources → Tabellen, dokumentierte Spalten mit Typen aus catalog.json, not_null-/unique-Tests → Nullbarkeit und Schlüssel, depends_on → Lineage; vorhandene Tabellen werden angereichert statt dupliziert) und Open-Data-Contract-Standard-Dateien (v3 schema/properties oder v2 dataset/columns: classification → Sensitivität, businessName → Business Term, primaryKey/required → Schlüssel und Nullbarkeit; Vertrag, Status, Domäne, Datenprodukt und Team in der Business Definition). Seit v1.60 laufen die API-Konnektoren (OData/SuccessFactors, Kafka Schema Registry, Power BI, Informatica) direkt im Katalogserver; nur DuckDB, Lake-Dateien, SQL-Dialekte und JDBC brauchen den optionalen Python-Inspector-Dienst. Auf Installationen ohne ihn (z. B. Databricks Apps) sind diese Einträge ausgeblendet und der Dialog nennt die Alternative: Datenbanken in Unity Catalog registrieren (Lakehouse Federation) und über die Unity-Catalog-Synchronisation laden.` },
      { icon: "shield", title: "Stewardship: Zertifizierung, Reviews, Ownership-Attestierung", body: `Auf dem Governance-Reiter einer Tabelle kann der zuständige Owner oder Steward die Tabelle **endorsen** (vertrauenswürdig, geprüft — zählt als Review), sie mit optionaler Nachfolgetabelle und Begründung **deprecaten** (Konsumenten sehen Badge und Nachfolger auf der Tabelle, den Schema-Karten und im Dashboard), die Zertifizierung entfernen, sie **als geprüft markieren** und einen **Review-Zyklus** setzen (90/180/365 Tage). Owner **bestätigen ihre Ownership** auf Tabellen, Schemas, Datenbanken und Domänen, auf denen sie explizit gesetzt sind; die Richtlinie (Governance-Übersicht, Admins) legt fest, wie oft — Standard alle 180 Tage. Fällige und überfällige Reviews und Attestierungen erscheinen unter Mein Dashboard › Stewardship-Aufgaben mit Ein-Klick-Aktionen; einmal täglich erhalten die Verantwortlichen eine In-App-Erinnerung (E-Mail bei konfiguriertem SMTP), höchstens alle 7 Tage pro Objekt. Nur der Owner attestiert; Stewards prüfen und zertifizieren. MCP-Agenten nutzen certify_table, review_table und list_stewardship_tasks.` },
      { icon: "server", title: "Backups & Jobs (Admins)", body: `Admin › Backups & Jobs schreibt täglich zur konfigurierten Uhrzeit (und auf Knopfdruck) einen gezippten Katalog-Dump auf den Server — plus einen vollständigen SQL-Dump der gesamten Datenbank, wenn mysqldump installiert ist; die Aufbewahrung ist einstellbar. **Prüfen** führt eine Restore-Übung aus: Die Datei wird erneut gelesen, Struktur und referenzielle Integrität geprüft und die Datensatzzahlen mit dem Live-Katalog verglichen. **Wiederherstellen** spielt ein Backup über den normalen Restore-Job ein, Downloads liefern die Dateien. Die Seite listet außerdem die letzten Hintergrund-Jobs (Importe, Restores, Backups) mit Ergebnis; die Liste liegt in der Datenbank und überlebt Neustarts — ein Job, der während eines Neustarts lief, wird als unterbrochen angezeigt.` },
      { icon: "message", title: "Kollaboration: Diskussion, Fragen, Bewertungen, Nutzung", body: `Jede Tabelle hat einen Reiter **Diskussion** (Datenprodukte zeigen die Diskussion unter ihren Tabellen): Alle angemeldeten Nutzer können Kommentare schreiben, **Fragen** stellen und beantworten. Eine Frage benachrichtigt den effektiven Data Steward und Owner (In-App, E-Mail mit SMTP) in deren Sprache; eine Antwort benachrichtigt den Fragesteller; Fragesteller, Stewards und Admins markieren eine Frage als **gelöst**. Offene Fragen an dich — und deine eigenen — stehen unter Mein Dashboard › Fragen. Tabellen und Datenprodukte tragen eine **Sternebewertung** (1–5, eine Stimme pro Person, Durchschnitt im Kopf). Der Katalog erfasst außerdem die **Nutzung**: Aufrufe (einer pro Person und Objekt je zehn Minuten), Suchbegriffe und Exporte. Die Nutzungszeile einer Tabelle steht auf ihren Reitern Governance und Diskussion; das Nutzungs-Panel des Dashboards zeigt die meistaufgerufenen Tabellen, die häufigsten Suchbegriffe und die bestbewerteten Tabellen für 7 bis 365 Tage. MCP-Agenten nutzen get_discussion, list_open_questions und add_comment; get_table enthält Bewertung, offene Fragen und Nutzung.` },
      { icon: "key", title: "OAuth 2.1 für MCP-Clients", body: `Neben Agent-Schlüsseln können sich MCP-Clients (Claude, IDE-Assistenten, Agenten-Frameworks) per OAuth 2.1 **als du** verbinden: Der Client findet /.well-known/oauth-protected-resource und /.well-known/oauth-authorization-server, registriert sich dynamisch (RFC 7591), schickt dich auf eine Zustimmungsseite (ggf. zuerst anmelden) und erhält ein Access-Token mit PKCE (S256, verpflichtend). Tokens sind opak, laufen nach einer Stunde ab und werden mit rotierenden Refresh-Tokens erneuert (30 Tage); der Scope catalog:write wird nur Admins und Data Stewards gewährt — alle anderen erhalten catalog:read. Jede Änderung wird unter deinem Namen auditiert. Das Schlüsselsymbol › **Verbundene MCP-Anwendungen** listet deine Verbindungen und trennt sie auf Wunsch (alle Tokens verfallen sofort); Admins sehen alle Verbindungen unter Benutzer. Jedes Credential — OAuth-Token, Agent-Schlüssel oder statisches Token — ist ratenbegrenzt (Standard 300 Anfragen und 60 Schreibaufrufe pro Minute; HTTP 429 mit Retry-After).` },
      { icon: "key", title: "Identität: SSO erzwingen, Gruppen → Rollen, Proxy-Anmeldung", body: `Admins können **SSO erzwingen**: Alle melden sich über Entra ID an, die Passwort-Anmeldung bleibt nur den aufgeführten **Break-Glass-Konten** (dein Konto wird bei leerer Liste eingetragen) — der Anmeldebildschirm zeigt dann den Microsoft-Button und einen kleinen Link „Break-Glass-Anmeldung“. Die **Gruppen → Rollen-Zuordnung** (Admin › Benutzer) leitet Katalogrollen aus den Gruppen des Identity-Providers ab: Entras groups-Claim (Objekt-IDs oder Namen) und App-Rollen, oder — im Header-Modus — der Gruppen-Header des Proxys bzw. die Databricks-Kontogruppen. Regeln bestimmen die Rollen neu angelegter Konten; mit „Rollen folgen Gruppen“ werden sie bei jeder Anmeldung erneut angewandt, Nutzer ohne Treffer erhalten die Standardrollen oder werden abgewiesen. Der letzte Admin wird nie herabgestuft. Im **Header-Modus** (AUTH_MODE=header, z. B. als Databricks App oder hinter oauth2-proxy) vertraut der Katalog den Identitäts-Headern des vorgeschalteten Proxys, legt Konten beim ersten Kontakt an (AUTH_BOOTSTRAP_ADMINS werden Admins) und zeigt kein Login-Formular; ein Shared-Secret-Header schützt den Node-Port. MCP-Schlüssel und -Tokens sind davon unberührt.` },
      { icon: "server", title: "Betrieb: Datenbank-Engines, Backup-Speicher, Health, externer Scheduler", body: `Der Server läuft auf **MariaDB (Standard) oder PostgreSQL / Databricks Lakebase** (DB_DRIVER=postgres; gleiches SQL im Code, übersetztes DDL, tsvector-Volltextsuche, pg_dump-Backups; Lakebase-Zugangsdaten werden mit DB_PASSWORD_PROVIDER=databricks je Verbindung geholt). Backups gehen in ein **lokales Verzeichnis, einen S3-kompatiblen Bucket, einen Azure-Blob-Container oder ein Unity-Catalog-Volume** (BACKUP_STORAGE=local|s3|azure|databricks); Wiederherstellung, Restore-Übungen und Downloads lesen aus demselben Speicher. **GET /healthz** meldet die Bereitschaft (Datenbank, Katalogversion, laufende Jobs, Speicher) für Monitoring und Plattform-Health-Checks. Die geplanten Aufgaben — Backup, Stewardship-Erinnerungen, Nutzungsbereinigung, Unity-Catalog-Sync — lassen sich mit **POST /admin/tasks/<name>/run** auf Abruf starten (Admin-Session oder TASKS_TOKEN-Bearer); mit SCHEDULER=external sind die internen Timer aus und ein Plattform-Scheduler (cron, Databricks Job) steuert sie. SIGTERM fährt den Dienst innerhalb von 15 Sekunden sauber herunter: laufende Jobs werden als unterbrochen markiert, der Pool geschlossen. Dump-Export, Backups, CSV-/OKF-Exporte und der CSV-Import streamen Attribute Tabelle für Tabelle, sodass auch 400.000 Attribute nie auf einmal im Speicher liegen.` },
      { icon: "upload", title: "Geplante Unity-Catalog-Synchronisation", body: `Admin › Backups & Jobs › **Geplante Synchronisation**: Ein Sync-Profil benennt einen Databricks-Workspace, einen Unity-Catalog-Katalog, Ziel-Data-Hub-Type / Data Hub / Layer, die Authentifizierung (Personal Access Token, Service Principal oder die eigene App-Identität auf Databricks Apps), einen Zeitplan (manuell, stündlich, täglich zu einer Uhrzeit) und einen Modus. **Nur Bericht** protokolliert die Abweichung — neue Schemas, Tabellen und Spalten, entfernte Tabellen und Spalten, geänderte Spaltentypen — und benachrichtigt die zuständigen Stewards und Owner in ihrer Sprache (Admins, wenn niemand zuständig ist); **Übernehmen** importiert zusätzlich neue Objekte, aktualisiert Spaltentypen und löscht auf Wunsch Tabellen und Spalten, die aus Unity Catalog verschwunden sind (Lineage optional). Jeder Lauf wird auditiert; das letzte Ergebnis mit Beispielen steht am Profil. „Verbindung testen“ zählt Schemas, Tabellen und Spalten, ohne den Katalog anzufassen; „Jetzt ausführen“ ignoriert den Zeitplan. **Write-back (v1.64):** Ein Profil kann Katalog-Metadaten nach jedem Lauf oder auf Knopfdruck auch nach Unity Catalog zurückschreiben — Beschreibungen als Kommentare, Data Owner / Data Steward / Datendomäne / Sensitivität / Klassifizierung als UC-Tags, Data Hub / Layer / Land als Katalog-Properties; nur Unterschiede, nichts wird angelegt oder gelöscht, kein Browser nötig. Im Profil aktivieren, SQL-Warehouse-ID für Tags und Spaltenkommentare eintragen, mit dem Wolken-Button vorab prüfen, mit „Zurückschreiben“ ausführen; das Ergebnis steht unter dem Profil und im Audit-Trail. Ohne Warehouse-ID werden die Änderungen, die SQL brauchen (Spaltenkommentare, Tabellen-Properties, Tags), als übersprungen gezählt — Kommentare und Katalog-Properties werden trotzdem geschrieben, der Lauf schlägt nicht fehl. **v1.66:** Die SQL-Warehouse-ID ist eine Profileinstellung für beide Richtungen — beim Import werden mit „Governance-Tags importieren“ die Tags (Sensitivität, Klassifizierung, Data Owner / Steward / Domäne) gelesen, beim Write-back Tags und Spaltenkommentare geschrieben. Der einmalige Import aus dem Import-Menü nutzt dieselbe Mechanik und kann als Profil gespeichert werden.` },
      { icon: "boxes", title: "Dashboard", body: `Die Startseite zeigt Katalog-KPIs: Data Hub Types und Objekte, Datenprodukte, verschiedene Owner und Stewards sowie die Governance-Abdeckung — der Anteil der Datenbanken mit Owner, der Tabellen mit Data Steward und der Datenprodukte mit Owner und Steward. Seit v1.66 werden die Abdeckungs-KPIs für Attribute (Tabellen und Attribute mit Beschreibung, Attribute mit Sensitivität und Business-Begriff) auf dem Server berechnet (/api/stats) und sind damit auch für große, lazy geladene Kataloge exakt.` },
      { icon: "shield", adminOnly: true, title: "Admin-Menü (nur Admins)", body: `• **Benutzer** — Personen per E-Mail mit Rollen einladen (Mehrfachauswahl; ohne SMTP wird der Einladungslink zum Kopieren gezeigt), Name, E-Mail und Rollen bearbeiten, 2FA-/Entra-Status sehen, Konten löschen; Agents per Name mit MCP-Schlüssel und Scope lesen/schreiben anlegen; Entra-ID-Anmeldung konfigurieren. Der letzte Admin kann weder herabgestuft noch gelöscht werden. Einladungslinks werden einmal gezeigt (Tokens liegen gehasht in der Datenbank) — *Erneuern* stellt einen neuen Link aus, *Zurückziehen* löscht die Einladung. Der Kreispfeil neben einem Passwort-Konto stellt einen **Passwort-Reset-Link** aus (24 Stunden, einmalig, per E-Mail wenn SMTP konfiguriert ist).
• **Governance Overview** — BPO je Data Hub und Owner/Stewards je Datendomäne zuordnen, sehen, wer die Workflow-Rollen hält, das Personenverzeichnis pflegen.
• **Audit-Trail** — das vollständige Änderungsprotokoll des Katalogs.
• **Dump / Wiederherstellen** — den kompletten Katalog als JSON herunterladen (Backup) und aus einem Dump ersetzen; Wiederherstellungen werden auditiert, Konten bleiben unberührt.
• **Glossarbegriffe exportieren** — alle Begriffe als JSON (Anhänge als Referenzen).` },
    ],
  },
  pl: {
    title: "Pomoc — przewodnik po funkcjach",
    sub: "Jak działa Alassio Data Catalog, funkcja po funkcji. Role: Admin > Steward danych (zapis/edycja/import) > Gość (tylko odczyt).",
    sections: [
      { icon: "boxes", title: "Typy hubów, huby danych i hierarchia", body: `Katalog ma strukturę Typ hubu danych → Hub danych → Baza danych → Schemat → Tabela → Atrybut. Typy hubów (Finance, HR, Sales, SOURCE) grupują huby według segmentu biznesowego — SOURCE zawiera ogólne systemy źródłowe, istnieje od pierwszego uruchomienia i w drzewie jest zawsze ostatni, oddzielony linią; hub danych to dowolnie nazwana grupa baz w obrębie typu, np. SALES_DE → BRONZE / SILVER / GOLD, z BPO, opcjonalną domeną danych i opcjonalnym linkiem do LeanIX. Wybierz typ, aby zobaczyć i tworzyć jego huby; wybierz hub, aby zobaczyć i tworzyć jego bazy. Nawiguj przez drzewo lub karty; ścieżka nawigacyjna zawsze pokazuje, gdzie jesteś.` },
      { icon: "search", title: "Wyszukiwanie", body: `Pole wyszukiwania znajduje obiekty po nazwach, opisach, definicjach biznesowych, pojęciach słownika, tagach, typach danych i stewardach, sortując według trafności. Zawęź wyniki filtrami (typ obiektu, hub, warstwa medallion, wrażliwość). Kliknięcie wyniku przenosi do obiektu.` },
      { icon: "pencil", title: "Edycja metadanych", body: `Stewardzi danych i administratorzy tworzą, edytują i usuwają wszystkie obiekty. Każda tabela ma metadane techniczne (atrybuty, typy danych, ograniczenia, wrażliwość) i biznesowe (definicja biznesowa, pojęcia, tagi) na osobnych zakładkach.` },
      { icon: "shield", title: "Governance", body: `Bazy należą do domen danych; huby mają BPO, domeny właściciela i stewarda, tabele mogą mieć własnego stewarda. Przegląd governance zarządza przypisaniami i osobami; zakładka Governance każdej tabeli pokazuje efektywne odpowiedzialności i oznacza atrybuty PII.` },
      { icon: "lineage", title: "Lineage danych", body: `Bazy mają warstwę medallion (bronze → silver → gold), którą dziedziczą tabele. Widok lineage pokazuje tylko tabele z powiązaniami; wybierz produkt danych (schemat w bazie gold), aby prześledzić cały łańcuch zasilania. Pełny lineage otwierasz z pulpitu, ze strony produktu (z filtrem) lub z zakładki Lineage tabeli. Kliknięcie źródła, odbiorcy lub strzałki otwiera mapowanie atrybutów. Powiązania tabel importowanych z Unity Catalog są zablokowane — zarządza nimi Databricks.` },
      { icon: "upload", title: "Menu Import", body: `Wszystko, co wprowadza metadane do katalogu. Pozycje widoczne są tylko dla uprawnionych ról.

• **Importuj CSV** (stewardzi, admini) — wczytuje format CSV katalogu (wiersz na atrybut). Brakujące typy, huby, bazy, schematy, tabele, atrybuty, domeny i osoby są tworzone automatycznie; istniejące obiekty są dopasowywane po nazwie i uzupełniane. Import działa jako zadanie w tle na serwerze z oknem postępu (przesyłanie → odczyt → zapis); pliki z setkami tysięcy wierszy wczytują się w minuty, a przeglądarka pozostaje responsywna; powyżej 5 000 atrybutów katalog przełącza się na leniwe ładowanie.
• **Unity Catalog** (admini) — od v1.66 działa na serwerze: wybierz profil synchronizacji lub podaj jednorazowe połączenie (URL workspace, token osobisty / service principal / tożsamość aplikacji, opcjonalnie ID SQL warehouse), połącz, wybierz katalog oraz docelowy typ, hub i warstwę; import działa jako zadanie serwera z oknem postępu i przynosi schematy, tabele, kolumny, opcjonalnie lineage oraz — z warehouse — tagi governance. Token służy tylko do tego importu i nigdy nie trafia do przeglądarki; „Zapisz jako profil synchronizacji” zachowuje połączenie do uruchomień zaplanowanych. Pakiety Power BI, dbt i ODCS są również parsowane i stosowane na serwerze.
• **Wczytaj źródło** (admini) — podpowiada wcześniej użyte źródła (hasła nie są zapisywane) i odczytuje systemy źródłowe na żywo do typu SOURCE: pliki baz DuckDB na serwerze (tylko odczyt), pliki data lake (Parquet/CSV/JSON/Delta/Iceberg lokalnie, na S3 lub Azure przez DuckDB), MySQL/MariaDB, PostgreSQL, Microsoft SQL Server, Oracle, Snowflake, IBM DB2, SAP HANA przez SQLAlchemy, dowolny dialekt przez URL SQLAlchemy, dowolną bazę przez ogólny konektor JDBC, SAP SuccessFactors i dowolne usługi OData v2/v4 (SAP S/4HANA), Kafka Schema Registry (tematy → tabele) oraz Informatica Data Catalog przez API. Importy pakietowe wczytują kilka baz wraz z lineage do wybranego huba: Power BI (obszary robocze, zbiory danych, raporty przez Scanner API administratora), projekty dbt (manifest.json + catalog.json, lineage z depends_on) i kontrakty danych ODCS (YAML/JSON). Dane logowania są używane raz; te źródła nie mają zapisu zwrotnego.` },
      { icon: "download", title: "Menu Eksport", body: `Wszystko, co wyprowadza metadane z katalogu. Eksport CSV i OKF dostępny jest dla wszystkich ról; zapis zwrotny jest otwarty dla każdej roli i zapisuje własne zmiany. Wspólny dialog wyboru: zaznacz całe typy, bazy, schematy lub pojedyncze tabele.

• **Eksportuj CSV** — wiersz na atrybut ze wszystkimi kolumnami technicznymi, biznesowymi i governance; plik importuje się 1:1.
• **Eksportuj OKF** — pakiet Open Knowledge Format v0.2 jako zip: pliki Markdown z nagłówkiem YAML, jeden koncept na plik, powiązane jak graf. Dla agentów AI, wiki LLM i baz wiedzy — ten sam pakiet dostępny jest agentom przez MCP.
• **Zapisz z powrotem do UC** (wszystkie role, v1.77) — najpierw otwiera podgląd: katalog jest porównywany z Unity Catalog, a okno wymienia **Twoje własne** oczekujące zmiany (opisy, właściciele, stewardzi, domeny, wrażliwość, klasyfikacja — przypisane na podstawie dziennika audytu), ile zmian należy do których innych użytkowników i co nie ma zarejestrowanego autora. Zapisywane są tylko Twoje zmiany — każdy użytkownik sam zapisuje swoje; administratorzy dodatkowo te bez autora. Opisy stają się komentarzami, wrażliwość/klasyfikacja tagami kolumn, Data Owner / Data Steward / Data Domain tagami katalogu, warstwa i data hub właściwościami katalogu — tylko różnice, nic strukturalnego nie jest w Databricks tworzone, zmieniane ani usuwane. Połączenie i poświadczenia pochodzą z profilu synchronizacji (Admin › Kopie zapasowe i zadania); automatyczny zapis zwrotny profilu po każdym uruchomieniu pozostaje ustawieniem administratora, które zapisuje wszystkie zmiany.` },
      { icon: "history", title: "Dziennik audytu i wersjonowanie", body: `Każda zmiana każdego rekordu jest logowana z użytkownikiem, czasem i wartościami pól przed/po. Widok audytu pokazuje pełną historię; przycisk Historia przy każdym obiekcie pokazuje jego wersje z przywracaniem poprzednich wersji lub usuniętych rekordów (stewardzi i admini).` },
      { icon: "key", title: "Twoje konto i 2FA", body: `Ikona klucza otwiera ustawienia bezpieczeństwa: włącz uwierzytelnianie dwuskładnikowe, skanując kod QR aplikacją TOTP (lub wpisując klucz ręcznie). Nowym użytkownikom 2FA proponowane jest zaraz po aktywacji konta — można je pominąć i włączyć później. Jeśli admin włączył logowanie Entra ID, możesz logować się kontem Microsoft; MFA Entra zastępuje wtedy lokalne 2FA. Po trzech nieudanych próbach logowanie jest spowalniane; po dziesięciu konto jest blokowane na 15 minut. **Hasło**: w tym samym oknie zmienisz hasło (wymagane obecne hasło; pozostałe sesje zostaną wylogowane). Nie pamiętasz go? Przy skonfigurowanej poczcie ekran logowania oferuje *Nie pamiętasz hasła?* i wysyła link resetujący ważny 24 godziny; w przeciwnym razie admin wystawia go w Admin › Użytkownicy. Reset kończy wszystkie sesje konta; 2FA pozostaje włączone.` },
      { icon: "book", title: "Słownik", body: `Przycisk Słownik listuje wszystkie pojęcia biznesowe z wyszukiwarką. Pojęcie to przede wszystkim definicja tekstowa; może wskazywać dowolną liczbę obiektów katalogu (klikalne), zawierać nazwane linki do zasobów zewnętrznych i załączniki (do 15 MB każdy, do pobrania dla wszystkich ról). Stewardzi i admini tworzą, edytują i usuwają pojęcia; zmiany są audytowane. Przy tabelach i atrybutach pole Pojęcie słownika podpowiada nazwy; nieznane pojęcie jest tworzone automatycznie.` },
      { icon: "store", title: "Marketplace i workflow produktu danych", body: `• **Poproś o dostęp** (wszystkie role): wybierz produkt danych, podaj cel, wyślij; admini zatwierdzają lub odrzucają, wnioskodawca jest powiadamiany.
• **Zaprojektuj nowy produkt danych** (kierownicy projektu, admini): nazwa, opis, typ hubu, projekt (wymagany) i przypadek użycia (wymagany) — wybrane tabele SOURCE otrzymują tagi Data Product, Project i Use Case przy złożeniu; edycja wyboru dodaje lub usuwa je, wycofanie lub usunięcie projektu usuwa je. Sekcja Advanced zbiera częstotliwość odświeżania, klasyfikację, historyzację, typ danych, termin i retencję (np. 3 miesiące).

Wybór wniosku pokazuje trzy fazy z ich stanem i ostatnią historią:

• **1 · Pozyskanie danych** — złożony projekt trafia automatycznie do analityka biznesowego, który go doprecyzowuje (może edytować wpisy), oznacza „Projekt doprecyzowany” i dokumentuje pozyskanie (system źródłowy, BPO, link LeanIX, steward); „Wyślij i poproś o zatwierdzenie” kieruje go bezpośrednio do BPO. Przycisk Podgląd pokazuje wszystkie wpisy w układzie formularzy. BPO zatwierdza użycie danych (załączając dokument) — projekt trafia automatycznie do Data Ingestion — lub odrzuca z uzasadnieniem, co cofa go do analityka. Data Ingestion potwierdza załadowane tabele wraz z lokalizacją, co automatycznie przekazuje projekt do doprecyzowania, lub zwraca go.
• **2 · Doprecyzowanie produktu danych** — analityk doprecyzowuje produkt i kończy krok notatkami (np. gdzie jest udokumentowane w Confluence) oraz opcjonalnymi załącznikami; to automatycznie przekazuje go do rozwoju, albo analityk zwraca projekt.
• **3 · Rozwój i testy / Odbiór** — zespół rozwoju potwierdza kolejno Rozwój (z notatkami o wyniku), UAT i SIT (lub zwraca projekt na każdym z tych kroków); następnie zespół rozwoju dokumentuje wdrożenie na PRD, a kierownik projektu, który złożył projekt, dokonuje końcowego odbioru — gotowy produkt otrzymuje wtedy tagi Data Product, Project i Use Case; tabele źródłowe mają swoje tagi od złożenia projektu. Kroki „Projekt doprecyzowany”, „Doprecyzowanie zakończone”, Rozwój, UAT, SIT i „Released to PRD” otwierają okno z wymaganymi notatkami i opcjonalnymi załącznikami. Rozwinięty wniosek pokazuje po prawej każdy krok procesu jako kółko: zielone = zakończone, szare = otwarte, niebieska obwódka = bieżące.

Każdy wniosek pokazuje fazę i czyje działanie jest oczekiwane. Każdy krok powiadamia wnioskodawcę i następną rolę. Admini mogą usunąć każdy wniosek po podwójnym potwierdzeniu. Dokumentacja BPMN jest podlinkowana u góry Marketplace.` },
      { icon: "message", title: "Wiadomości", body: `Wiadomości są częścią Mojego pulpitu w sekcji „Czeka na moje działanie" (przycisk pulpitu pokazuje licznik nieprzeczytanych): powiadomienia workflow, decyzje o dostępie i zadania stewardów. Wiadomości linkują do listy wniosków lub tabeli; przy skonfigurowanym SMTP kopia idzie e-mailem. Kierownicy projektu i admini mogą na każdej tabeli „Poprosić o opisy biznesowe": steward otrzymuje wiadomość; bez stewarda właściciel danych jest proszony o jego wyznaczenie; bez właściciela — admini.` },
      { icon: "send", title: "Wnioski o dostęp (produkty danych)", body: `Schematy w bazie gold są produktami danych (np. Sales › SALES_DE › GOLD › partners). Każdy ma przycisk „Poproś o dostęp", który otwiera Marketplace z wybranym produktem.` },
      { icon: "tag", title: "Tagi Project i Use Case", body: `Tabele i produkty danych mają tagi „Project" i „Use Case" z jedną lub wieloma wartościami — ustawiane na stronie tabeli lub produktu przez właścicieli/stewardów albo automatycznie z projektu produktu. Są wyszukiwalne, eksportowane w CSV/OKF i zwracane przez MCP.` },
      { icon: "layers", title: "Odkrywaj produkty danych (kierownicy projektu, admini)", body: `Jedna strona ze stanem wszystkich produktów danych, filtrowana według domeny, projektu i przypadku użycia: ukończone (schematy w bazach gold i zakończone projekty) oraz każdy planowany lub wnioskowany produkt z fazą, dokładnym statusem i oczekiwaną osobą — posortowane według domeny i typu hubu. Wiersze otwierają schemat lub listę wniosków.` },
      { icon: "users", title: "Język", body: `Interfejs jest dostępny po angielsku, niemiecku, polsku, hiszpańsku, francusku i włosku — przełącz go selektorem obok Wyloguj (lub na ekranie logowania). Wybór jest zapisywany w koncie; powiadomienia otrzymujesz w tym języku.` },
      { icon: "layers", title: "Duże katalogi", body: `Powyżej 5 000 atrybutów katalog ładuje się leniwie: drzewo, tabele i pulpity pojawiają się od razu z licznikami, a atrybuty tabeli są pobierane przy jej otwarciu. Eksporty i zapis zwrotny automatycznie sięgają po pełny katalog.` },
      { icon: "usercog", title: "Mój pulpit", body: `Twój osobisty widok: role konta i pasujący rekord osoby z domenami; wszystko, co czeka na Twoje działanie (zatwierdzenia i potwierdzenia workflow, wnioski o dostęp do Twoich produktów, zadania stewarda i nieprzeczytane wiadomości); zainicjowane przez Ciebie wnioski i projekty z fazą i następnym krokiem; Twoje pojęcia słownika; oraz każdy hub, baza, schemat i tabela, gdzie jesteś BPO, właścicielem lub stewardem.` },
      { icon: "shield", title: "Uprawnienia — kto może co zmieniać", body: `Role konta decydują, czy możesz się logować i edytować; odpowiedzialności decydują, co. Osoba może mieć kilka ról — uprawnienia wynikają z najwyższej (Admin › Steward danych › Kierownik projektu › Analityk / Data Ingestion / Rozwój › Gość); kroki workflow adresują każdą rolę. Odpowiedzialności są osobowe: konto dopasowywane jest do katalogu osób po e-mailu (lub dokładnej nazwie).

• **Dziedziczenie**: własność i stewardship płyną w dół — hub (BPO) → domena → baza → schemat → tabela — i można je nadpisać na każdym poziomie. Typy hubów nie mają właściciela. Domeny danych też dziedziczą się w dół.
• **Admini**: zapraszają użytkowników, zmieniają strukturę, ustawiają BPO i właścicieli, przywracają historię — wszystko.
• **Właściciele danych**: ustawiają stewarda na swoich zasobach i poniżej; edytują tabele i atrybuty jak steward.
• **Stewardzi danych**: edytują tabele i atrybuty, dla których są efektywnym stewardem, w tym tworzą tabele w swoich schematach.
• **Lineage**: admini lub właściciel/steward jednej z dwóch tabel. **Słownik**: admini lub każdy z co najmniej jedną odpowiedzialnością.
• **Goście** i role workflow (kierownik projektu, Data Ingestion, rozwój): czytają wszystko, używają Marketplace i działają w workflow — bez edycji katalogu.
• **Agenci**: konta techniczne dla klientów MCP, bez roli governance, tworzone i usuwane tylko przez adminów; ich klucze (zakres odczyt lub zapis) są poświadczeniem dla POST /mcp.

Przyciski, których nie możesz użyć, są ukryte; serwer egzekwuje te same reguły przy każdym zapisie.` },
      { icon: "bot", title: "Serwer MCP dla agentów AI", body: `Katalog jest serwerem Model Context Protocol (Streamable HTTP, JSON-RPC 2.0) pod POST /mcp. Agenci — Claude, frameworki agentów, asystenci IDE — czytają, przeszukują i zmieniają katalog według tych samych reguł co UI; zarządzanie użytkownikami nie jest udostępnione. Każda zmiana agenta jest audytowana pod jego nazwą.

**Połączenie.** URL https://<serwer>/mcp z nagłówkiem Authorization: Bearer <klucz>; klucz to statyczny MCP_TOKEN lub klucz agenta wydany w zarządzaniu użytkownikami. Klienci obsługujący tylko stdio używają mostka npx mcp-remote.

**Metody.** initialize, ping, tools/list, tools/call, resources/list, resources/read. Przykład:
${EX_CALL}
**Odwołania** to ścieżki: baza, baza.schemat, baza.schemat.tabela, baza.schemat.tabela.atrybut (bez rozróżniania wielkości liter).

**Narzędzia.** Odczyt: get_overview, list_hubs, list_databases, list_schemas, list_tables, get_table, list_data_products, get_lineage, search_catalog, get_audit. Zapis: create/update/delete dla hubów, baz, schematów, tabel i atrybutów, add/remove lineage, map/unmap lineage attributes, export_okf. Klucze z zakresem odczyt są odrzucane przy narzędziach zapisujących.` },
      { icon: "json", title: "OKF przez MCP — jak agenci czytają katalog", body: `Cały katalog udostępniany jest jako pakiet Open Knowledge Format na dwa sposoby:

• **Zasoby** (zalecane do czytania): resources/list zwraca każdy plik konceptu jako okf://<ścieżka>; resources/read zwraca jego Markdown. Zacznij od okf://index.md i podążaj linkami w dół — agent czyta tylko to, czego potrzebuje.
${EX_READ}
• **Narzędzie export_okf**: opcjonalne hub, database, schema, table ograniczają pakiet do poddrzewa; format files (domyślnie) lub zip_base64.
${EX_OKF}
Plik konceptu ma nagłówek YAML (type, title, id, path, hub, data_hub, medallion_layer, data_product, steward, tags, provenance) oraz Markdown z opisem, definicją biznesową, governance, tabelą atrybutów i sekcjami lineage. Ten sam pakiet pobiera Eksport → Eksportuj OKF.` },
      { icon: "server", title: "Wczytywanie ogólnych źródeł danych (admini)", body: `Admini odczytują systemy źródłowe na żywo: pliki baz DuckDB na serwerze katalogu (natywny sterownik, tylko odczyt, z tekstami COMMENT ON i kluczami głównymi), MySQL/MariaDB, PostgreSQL, IBM DB2 i SAP HANA przez SQLAlchemy (lub dowolny dialekt przez URL SQLAlchemy), Microsoft SQL Server (pymssql), Oracle (oracledb thin) i Snowflake, pliki data lake przez DuckDB (Parquet/CSV/JSON/Delta/Iceberg — lokalnie, S3/MinIO, Azure Data Lake; każda ścieżka lub glob staje się tabelą typu FILE), SAP SuccessFactors i dowolne usługi OData v2/v4 przez $metadata (typy encji → tabele, klucze → klucze główne, etykiety SAP → opisy), Kafka Schema Registry (najnowszy schemat Avro/JSON Schema/Protobuf na subject → tematy jako tabele typu TOPIC, zagnieżdżone rekordy jako atrybuty z kropką, schemat klucza jako klucze główne key.*), inne systemy przez ogólny konektor JDBC oraz Informatica Data Catalog przez Catalog Search API. Wczytane bazy trafiają do typu SOURCE i nie mają zapisu zwrotnego. Źródła pakietowe trafiają do wybranego huba i wnoszą lineage: Power BI (Scanner API — obszar roboczy → baza, zbiór danych → schemat, tabele z kolumnami i miarami, raporty jako obiekty typu REPORT w schemacie „Reports” z lineage tabela zbioru → raport), dbt (modele/seeds/snapshoty/źródła → tabele, udokumentowane kolumny z typami z catalog.json, testy not_null/unique → nullowalność i klucze, depends_on → lineage; istniejące tabele są wzbogacane, nie duplikowane) oraz pliki Open Data Contract Standard (v3 schema/properties lub v2 dataset/columns: classification → wrażliwość, businessName → termin biznesowy, primaryKey/required → klucz i nullowalność; kontrakt, status, domena, produkt danych i zespół w definicji biznesowej). Od v1.60 konektory API (OData/SuccessFactors, Kafka Schema Registry, Power BI, Informatica) działają bezpośrednio w serwerze katalogu; tylko DuckDB, pliki lake, dialekty SQL i JDBC wymagają opcjonalnej usługi inspektora w Pythonie. W instalacjach bez niej (np. Databricks Apps) te pozycje są ukryte, a okno wskazuje alternatywę: zarejestruj bazy w Unity Catalog (Lakehouse Federation) i wczytaj je synchronizacją Unity Catalog.` },
      { icon: "shield", title: "Stewardship: certyfikacja, przeglądy, potwierdzanie własności", body: `Na zakładce Governance tabeli odpowiedzialny właściciel lub steward może **zatwierdzić** tabelę (endorsed — zaufana, sprawdzona; liczy się jako przegląd), **wycofać** ją z opcjonalną tabelą następczą i uzasadnieniem (odbiorcy widzą odznakę i następcę na tabeli, kartach schematu i w dashboardzie), usunąć certyfikację, **oznaczyć jako sprawdzoną** i ustawić **cykl przeglądów** (90/180/365 dni). Właściciele **potwierdzają własność** tabel, schematów, baz i domen, na których są ustawieni jawnie; polityka (Przegląd governance, admini) określa jak często — domyślnie co 180 dni. Należne i zaległe przeglądy oraz potwierdzenia pojawiają się w Mój pulpit › Zadania stewardship z akcjami jednym kliknięciem; raz dziennie odpowiedzialni dostają przypomnienie w aplikacji (e-mail przy skonfigurowanym SMTP), najwyżej co 7 dni na obiekt. Tylko właściciel potwierdza; stewardzi przeglądają i certyfikują. Agenci MCP używają certify_table, review_table i list_stewardship_tasks.` },
      { icon: "server", title: "Kopie zapasowe i zadania (admini)", body: `Admin › Kopie zapasowe i zadania zapisuje codziennie o ustawionej godzinie (i na żądanie) spakowany zrzut katalogu na serwerze — plus pełny zrzut SQL całej bazy, gdy zainstalowany jest mysqldump; retencja jest konfigurowalna. **Weryfikuj** wykonuje próbę odtworzenia: plik jest ponownie czytany, sprawdzana jest struktura i spójność referencyjna, a liczby rekordów porównywane z katalogiem na żywo. **Przywróć** odtwarza kopię przez zwykłe zadanie przywracania, pobrania dają pliki. Strona wyświetla też ostatnie zadania w tle (importy, przywracania, kopie) z wynikiem; lista jest w bazie i przetrwa restart usługi — zadanie działające podczas restartu jest oznaczone jako przerwane.` },
      { icon: "message", title: "Współpraca: dyskusja, pytania, oceny, użycie", body: `Każda tabela ma zakładkę **Dyskusja** (produkty danych pokazują dyskusję pod swoimi tabelami): każdy zalogowany może komentować, zadawać **pytania** i na nie odpowiadać. Pytanie powiadamia efektywnego stewarda i właściciela danych (w aplikacji, e-mail przy SMTP) w ich języku; odpowiedź powiadamia pytającego; pytający, stewardzi i admini oznaczają pytanie jako **rozwiązane**. Otwarte pytania skierowane do Ciebie — i Twoje własne — są w Mój pulpit › Pytania. Tabele i produkty danych mają **ocenę gwiazdkową** (1–5, jeden głos na osobę, średnia w nagłówku). Katalog rejestruje też **użycie**: wyświetlenia (jedno na osobę i obiekt na dziesięć minut), frazy wyszukiwania i eksporty. Wiersz użycia tabeli jest w zakładkach Governance i Dyskusja; panel Użycie na pulpicie pokazuje najczęściej wyświetlane tabele, najczęstsze frazy i najlepiej oceniane tabele dla 7–365 dni. Agenci MCP używają get_discussion, list_open_questions i add_comment; get_table zawiera ocenę, otwarte pytania i użycie.` },
      { icon: "key", title: "OAuth 2.1 dla klientów MCP", body: `Oprócz kluczy agentów klienci MCP (Claude, asystenci IDE, frameworki agentowe) mogą łączyć się **jako Ty** przez OAuth 2.1: klient odkrywa /.well-known/oauth-protected-resource i /.well-known/oauth-authorization-server, rejestruje się dynamicznie (RFC 7591), kieruje Cię na stronę zgody (w razie potrzeby najpierw logowanie) i otrzymuje token dostępu z PKCE (S256, obowiązkowo). Tokeny są nieprzezroczyste, wygasają po godzinie i są odnawiane rotującymi tokenami odświeżania (30 dni); zakres catalog:write dostają tylko admini i stewardzi danych — pozostali catalog:read. Każda zmiana jest audytowana pod Twoim nazwiskiem. Ikona klucza › **Połączone aplikacje MCP** pokazuje Twoje połączenia i pozwala je odłączyć (wszystkie tokeny natychmiast wygasają); admini widzą wszystkie połączenia w Użytkownikach. Każde poświadczenie — token OAuth, klucz agenta lub token statyczny — ma limit (domyślnie 300 żądań i 60 wywołań zapisu na minutę; HTTP 429 z Retry-After).` },
      { icon: "key", title: "Tożsamość: wymuszenie SSO, mapowanie grup → ról, logowanie przez proxy", body: `Admini mogą **wymusić SSO**: wszyscy logują się przez Entra ID, logowanie hasłem pozostaje tylko dla wskazanych **kont awaryjnych** (Twoje konto jest dodawane, gdy lista jest pusta) — ekran logowania pokazuje wtedy przycisk Microsoft i mały link „Logowanie awaryjne”. **Mapowanie grup → ról** (Admin › Użytkownicy) wyprowadza role katalogu z grup dostawcy tożsamości: claim groups Entra (identyfikatory lub nazwy) i role aplikacji albo — w trybie nagłówków — nagłówek grup proxy lub grupy konta Databricks. Reguły ustalają role nowo tworzonych kont; z opcją „role podążają za grupami” są stosowane przy każdym logowaniu, a użytkownicy bez dopasowania dostają role domyślne lub są odrzucani. Ostatni admin nigdy nie jest degradowany. W **trybie nagłówków** (AUTH_MODE=header, np. jako Databricks App lub za oauth2-proxy) katalog ufa nagłówkom tożsamości proxy, tworzy konta przy pierwszym kontakcie (AUTH_BOOTSTRAP_ADMINS zostają adminami) i nie pokazuje formularza logowania; nagłówek ze wspólnym sekretem chroni port Node. Klucze i tokeny MCP nie są objęte.` },
      { icon: "server", title: "Eksploatacja: silniki baz, magazyn kopii, health, zewnętrzny harmonogram", body: `Serwer działa na **MariaDB (domyślnie) lub PostgreSQL / Databricks Lakebase** (DB_DRIVER=postgres; ten sam SQL w kodzie, tłumaczone DDL, wyszukiwanie pełnotekstowe tsvector, kopie pg_dump; poświadczenia Lakebase pobierane per połączenie przy DB_PASSWORD_PROVIDER=databricks). Kopie trafiają do **katalogu lokalnego, bucketu zgodnego z S3, kontenera Azure Blob lub wolumenu Unity Catalog** (BACKUP_STORAGE=local|s3|azure|databricks); przywracanie, próby odtworzenia i pobieranie czytają z tego samego magazynu. **GET /healthz** raportuje gotowość (baza, wersja katalogu, aktywne zadania, pamięć) dla monitoringu i health checków platformy. Zadania zaplanowane — kopia, przypomnienia stewardship, czyszczenie użycia, synchronizacja Unity Catalog — można uruchomić na żądanie przez **POST /admin/tasks/<name>/run** (sesja admina lub bearer TASKS_TOKEN); przy SCHEDULER=external wewnętrzne timery są wyłączone i steruje nimi harmonogram platformy (cron, Databricks Job). SIGTERM zamyka usługę łagodnie w 15 sekund: trwające zadania są oznaczane jako przerwane, pula zamykana. Eksport dumpu, kopie, eksporty CSV/OKF i import CSV strumieniują atrybuty tabela po tabeli, więc nawet 400 000 atrybutów nigdy nie jest w pamięci naraz.` },
      { icon: "upload", title: "Zaplanowana synchronizacja Unity Catalog", body: `Admin › Kopie i zadania › **Zaplanowana synchronizacja**: profil synchronizacji wskazuje workspace Databricks, katalog Unity Catalog, docelowy typ data hub / data hub / warstwę, uwierzytelnianie (personal access token, service principal lub własna tożsamość aplikacji na Databricks Apps), harmonogram (ręcznie, co godzinę, codziennie o godzinie) i tryb. **Tylko raport** rejestruje rozbieżność — nowe schematy, tabele i kolumny, usunięte tabele i kolumny, zmienione typy kolumn — i powiadamia odpowiedzialnych stewardów i właścicieli w ich języku (adminów, gdy nikt nie odpowiada); **Zastosuj** dodatkowo importuje nowe obiekty, aktualizuje typy kolumn i, jeśli włączone, usuwa tabele i kolumny, które zniknęły z Unity Catalog (lineage opcjonalnie). Każde uruchomienie jest audytowane; ostatni wynik z przykładami widać na profilu. „Testuj połączenie” liczy schematy, tabele i kolumny bez dotykania katalogu; „Uruchom teraz” ignoruje harmonogram. **Zapis zwrotny (v1.64):** profil może też po każdym uruchomieniu lub na żądanie zapisywać metadane katalogu do Unity Catalog — opisy jako komentarze, właściciel / steward / domena / wrażliwość / klasyfikacja jako tagi UC, hub / warstwa / kraj jako właściwości katalogu; tylko różnice, nic nie jest tworzone ani usuwane, bez przeglądarki. Włącz w profilu, podaj ID SQL warehouse dla tagów i komentarzy kolumn, sprawdź podgląd przyciskiem chmury, uruchom „Zapisz zwrotnie”; wynik widać pod profilem i w dzienniku audytu. Bez ID warehouse zmiany wymagające SQL (komentarze kolumn, właściwości tabel, tagi) są liczone jako pominięte — komentarze i właściwości katalogu są mimo to zapisywane, a uruchomienie nie kończy się błędem. **v1.66:** ID SQL warehouse jest ustawieniem profilu dla obu kierunków — przy imporcie z włączonym „Importuj tagi governance” odczytywane są tagi (wrażliwość, klasyfikacja, właściciel / steward / domena), przy zapisie zwrotnym zapisywane są tagi i komentarze kolumn. Jednorazowy import z menu Import używa tego samego mechanizmu i może zostać zapisany jako profil.` },
      { icon: "boxes", title: "Pulpit", body: `Strona główna pokazuje KPI katalogu: typy hubów i obiekty, produkty danych, liczbę właścicieli i stewardów oraz pokrycie governance — odsetek baz z właścicielem, tabel ze stewardem i produktów z właścicielem i stewardem. Od v1.66 wskaźniki pokrycia atrybutów (tabele i atrybuty z opisem, atrybuty z wrażliwością i pojęciem biznesowym) są liczone na serwerze (/api/stats), więc są dokładne także dla dużych, leniwie ładowanych katalogów.` },
      { icon: "shield", adminOnly: true, title: "Menu Admin (tylko admini)", body: `• **Użytkownicy** — zapraszanie osób e-mailem z rolami (wielokrotny wybór; bez SMTP wyświetlany jest link do skopiowania), edycja nazwy, e-maila i ról, status 2FA/Entra, usuwanie kont; tworzenie agentów po nazwie z kluczem MCP i zakresem odczyt/zapis; konfiguracja logowania Entra ID. Ostatniego admina nie można zdegradować ani usunąć. Linki zaproszeń są pokazywane raz (tokeny są przechowywane jako skróty) — *Odnów* wystawia nowy link, *Wycofaj* usuwa zaproszenie. Przycisk ze strzałką obok konta z hasłem wystawia **link resetujący hasło** (24 godziny, jednorazowy, wysyłany e-mailem przy skonfigurowanym SMTP).
• **Przegląd governance** — przypisanie BPO do hubów i właścicieli/stewardów do domen, podgląd ról workflow, katalog osób.
• **Dziennik audytu** — pełny log zmian katalogu.
• **Zrzut / Przywróć** — pobranie całego katalogu jako JSON (kopia) i zastąpienie go ze zrzutu; przywracanie jest audytowane, konta pozostają nietknięte.
• **Eksportuj pojęcia słownika** — wszystkie pojęcia jako JSON (załączniki jako odwołania).` },
    ],
  },
  es: {
    title: "Ayuda — guía de funciones",
    sub: "Cómo funciona el Alassio Data Catalog, función por función. Roles: Admin > Data steward (escribir/editar/importar) > Invitado (solo lectura).",
    sections: [
      { icon: "boxes", title: "Tipos de hub, hubs de datos y jerarquía", body: `El catálogo se organiza como Tipo de hub de datos → Hub de datos → Base de datos → Esquema → Tabla → Atributo. Los tipos de hub (Finance, HR, Sales, SOURCE) agrupan hubs por segmento de negocio — SOURCE contiene los sistemas de origen genéricos, existe desde el primer arranque y siempre aparece el último en el árbol, separado por una línea; un hub de datos es un grupo de bases de datos con nombre libre dentro de un tipo, p. ej. SALES_DE → BRONZE / SILVER / GOLD, con su BPO, un dominio de datos opcional y un enlace opcional a LeanIX. Selecciona un tipo para ver y crear sus hubs; selecciona un hub para ver y crear sus bases de datos. Navega por el árbol o las tarjetas; la ruta de navegación siempre muestra dónde estás.` },
      { icon: "search", title: "Búsqueda", body: `El cuadro de búsqueda encuentra objetos por nombres, descripciones, definiciones de negocio, términos del glosario, etiquetas, tipos de dato y stewards, ordenados por relevancia. Acota con los filtros (tipo de objeto, hub, capa medallion, sensibilidad). Un clic en un resultado lleva directamente al objeto.` },
      { icon: "pencil", title: "Edición de metadatos", body: `Los data stewards y los administradores crean, editan y eliminan todos los objetos. Cada tabla tiene metadatos técnicos (atributos, tipos de dato, restricciones, sensibilidad) y de negocio (definición de negocio, términos, etiquetas) en pestañas separadas.` },
      { icon: "shield", title: "Gobernanza", body: `Las bases de datos pertenecen a dominios de datos; los hubs tienen un BPO, los dominios un propietario y un data steward, y las tablas pueden tener su propio steward. El resumen de gobernanza gestiona asignaciones y personas; la pestaña Gobernanza de cada tabla muestra las responsabilidades efectivas y marca los atributos PII.` },
      { icon: "lineage", title: "Linaje de datos", body: `Las bases de datos tienen una capa medallion (bronze → silver → gold) que sus tablas heredan. La vista de linaje muestra solo tablas con enlaces; elige un producto de datos (esquema en una base gold) para seguir toda su cadena de alimentación. Abre el linaje completo desde el panel, desde la página de un producto (prefiltrado) o desde la pestaña Linaje de una tabla. Al hacer clic en una fuente, un consumidor o una flecha se abre el mapeo de atributos. Los enlaces de tablas importadas de Unity Catalog están bloqueados: se gestionan en Databricks.` },
      { icon: "upload", title: "Menú Importar", body: `Todo lo que introduce metadatos en el catálogo. Las entradas solo aparecen para los roles autorizados.

• **Importar CSV** (stewards, admins) — carga el formato CSV del catálogo (una fila por atributo). Los tipos, hubs, bases, esquemas, tablas, atributos, dominios y personas que falten se crean automáticamente; los existentes se emparejan por nombre y se enriquecen. La importación se ejecuta en el servidor como tarea en segundo plano con diálogo de progreso (subida → lectura → escritura); archivos con cientos de miles de filas se cargan en minutos y el navegador sigue respondiendo; a partir de 5.000 atributos el catálogo pasa a carga diferida.
• **Unity Catalog** (admins) — desde v1.66 se ejecuta en el servidor: elige un perfil de sincronización o introduce una conexión puntual (URL del workspace, token personal / service principal / identidad de la app, ID del SQL warehouse opcional), conecta, elige el catálogo y el tipo, data hub y capa de destino; la importación se ejecuta como trabajo del servidor con diálogo de progreso y trae esquemas, tablas, columnas, linaje opcional y — con warehouse — las etiquetas de gobierno. El token solo se usa para esta importación y nunca llega al navegador; «Guardar como perfil de sincronización» conserva la conexión para ejecuciones programadas. Los paquetes de Power BI, dbt y ODCS también se analizan y aplican en el servidor.
• **Cargar fuente** (admins) — ofrece fuentes usadas anteriormente (las contraseñas nunca se guardan) e inspecciona sistemas fuente en vivo hacia el tipo SOURCE: archivos de base de datos DuckDB en el servidor (solo lectura), archivos de data lake (Parquet/CSV/JSON/Delta/Iceberg locales, en S3 o Azure vía DuckDB), MySQL/MariaDB, PostgreSQL, Microsoft SQL Server, Oracle, Snowflake, IBM DB2, SAP HANA vía SQLAlchemy, cualquier dialecto vía URL SQLAlchemy, cualquier base vía el conector JDBC genérico, SAP SuccessFactors y cualquier servicio OData v2/v4 (SAP S/4HANA), Kafka Schema Registry (topics → tablas) e Informatica Data Catalog vía su API. Las importaciones en paquete cargan varias bases con linaje en un hub a elegir: Power BI (áreas de trabajo, conjuntos de datos, informes vía la Scanner API de administración), proyectos dbt (manifest.json + catalog.json, linaje desde depends_on) y contratos de datos ODCS (YAML/JSON). Las credenciales se usan una vez; estas fuentes no tienen escritura de vuelta.` },
      { icon: "download", title: "Menú Exportar", body: `Todo lo que saca metadatos del catálogo. Exportar CSV y OKF están disponibles para todos los roles; la escritura de vuelta está abierta a todos los roles y escribe tus propios cambios. Los tres comparten el mismo diálogo de selección: marca tipos, bases, esquemas o tablas.

• **Exportar CSV** — una fila por atributo con todas las columnas técnicas, de negocio y de gobernanza; el archivo se reimporta 1:1.
• **Exportar OKF** — un paquete Open Knowledge Format v0.2 en zip: archivos Markdown con frontmatter YAML, un concepto por archivo, enlazados como grafo. Pensado para agentes de IA, wikis LLM y bases de conocimiento; el mismo paquete está disponible para agentes vía MCP.
• **Escribir de vuelta en UC** (todos los roles, v1.77) — abre primero una vista previa: el catálogo se compara con Unity Catalog y el diálogo lista **tus propios** cambios pendientes (descripciones, propietarios, stewards, dominios, sensibilidad, clasificación — atribuidos mediante el registro de auditoría), cuántos cambios pertenecen a qué otros usuarios y qué no tiene autor registrado. Solo se escriben tus propios cambios — cada usuario escribe los suyos; los administradores además los que no tienen autor. Las descripciones se convierten en comentarios, sensibilidad/clasificación en etiquetas de columna, Data Owner / Data Steward / Data Domain en etiquetas del catálogo, capa y data hub en propiedades del catálogo — solo diferencias, nunca se crea, altera ni elimina nada estructural en Databricks. La conexión y las credenciales provienen de un perfil de sincronización (Admin › Copias y trabajos); la escritura automática de un perfil tras cada ejecución sigue siendo un ajuste de administrador que escribe todos los cambios.` },
      { icon: "history", title: "Auditoría y versionado", body: `Cada cambio de cada registro se registra con usuario, fecha y valores antes/después por campo. La vista de auditoría muestra el historial completo; el botón Historial de cada objeto muestra sus versiones con restauración de versiones anteriores o registros eliminados (stewards y admins).` },
      { icon: "key", title: "Tu cuenta y 2FA", body: `El icono de la llave abre la configuración de seguridad: activa la autenticación de dos factores escaneando un código QR con una app TOTP (o introduciendo la clave manualmente). A los nuevos usuarios se les ofrece 2FA justo tras activar la cuenta; se puede omitir y activar más tarde. Si un admin ha activado el inicio de sesión con Entra ID, puedes entrar con tu cuenta Microsoft; el MFA de Entra sustituye al 2FA local. Tras tres intentos fallidos cada intento se ralentiza; tras diez la cuenta se bloquea 15 minutos. **Contraseña**: en el mismo diálogo cambias tu contraseña (se requiere la actual; tus otras sesiones se cierran). ¿La olvidaste? Con el correo configurado, la pantalla de inicio ofrece *¿Olvidaste tu contraseña?* y envía un enlace de restablecimiento válido 24 horas; si no, un admin lo emite en Admin › Usuarios. Un restablecimiento cierra todas las sesiones de la cuenta; la 2FA sigue activa.` },
      { icon: "book", title: "Glosario", body: `El botón Glosario lista todos los términos de negocio con buscador. Un término es ante todo una definición de texto libre; puede enlazar cualquier número de entidades del catálogo (clicables), llevar URLs a recursos externos y tener archivos adjuntos (máx. 15 MB cada uno, descargables por todos los roles). Stewards y admins crean, editan y eliminan términos; los cambios se auditan. En tablas y atributos el campo Término del glosario sugiere los nombres; un término desconocido se crea automáticamente.` },
      { icon: "store", title: "Marketplace y flujo del producto de datos", body: `• **Solicitar acceso** (todos los roles): elige un producto de datos, indica el propósito, envía; los admins aprueban o rechazan y se notifica al solicitante.
• **Diseñar un nuevo producto de datos** (jefes de proyecto, admins): nombre, descripción, tipo de hub, proyecto (obligatorio) y caso de uso (obligatorio) — las tablas SOURCE seleccionadas reciben las etiquetas Data Product, Project y Use Case al enviar; editar la selección las añade o quita, retirar o eliminar el diseño las quita. La sección Advanced recoge frecuencia de refresco, clasificación, historización, tipo de dato, fecha necesaria y retención (p. ej. 3 meses).

Seleccionar una solicitud muestra sus tres fases con su estado y el historial reciente:

• **1 · Obtención de datos** — un diseño enviado pasa automáticamente al analista de negocio, que lo refina (puede editar las entradas), lo marca como «Diseño refinado» y documenta la obtención (sistema fuente, BPO, enlace LeanIX, steward); «Enviar y solicitar aprobación» lo envía directamente al BPO. Un botón Ver muestra todas las entradas con el mismo diseño que los formularios. El BPO aprueba el uso (adjuntando el documento) — el diseño pasa automáticamente a Data Ingestion — o lo rechaza con motivo, lo que lo devuelve al analista. Data Ingestion confirma las tablas ingeridas con su ubicación, lo que lo envía automáticamente al refinamiento, o lo devuelve.
• **2 · Refinamiento del producto de datos** — el analista refina el producto y completa el paso con notas (p. ej. dónde está documentado en Confluence) y archivos adjuntos opcionales; esto lo envía automáticamente a desarrollo, o el analista lo devuelve.
• **3 · Desarrollo y pruebas / Aprobación** — el equipo de desarrollo confirma sucesivamente Desarrollo (con notas del resultado), UAT y SIT (o devuelve el diseño en cualquiera de ellos); después el equipo de desarrollo documenta la liberación a PRD y el jefe de proyecto que envió el diseño da la aprobación final — el producto terminado recibe entonces las etiquetas Data Product, Project y Use Case; las tablas fuente llevan las suyas desde el envío del diseño. «Diseño refinado», «Refinamiento completado», Desarrollo, UAT, SIT y «Released to PRD» abren cada uno un diálogo con notas obligatorias y archivos adjuntos opcionales. La solicitud desplegada muestra a la derecha cada paso del proceso como un círculo: verde = completado, gris = abierto, anillo azul = actual.

Cada solicitud muestra su fase y de quién se espera acción. Cada paso notifica al solicitante y al siguiente rol. Los admins pueden eliminar cualquier solicitud tras una doble confirmación. La documentación BPMN está enlazada arriba en el Marketplace.` },
      { icon: "message", title: "Mensajes", body: `Los mensajes forman parte de Mi panel en «Pendiente de mi acción» (el botón del panel lleva el contador de no leídos): notificaciones del flujo, decisiones sobre accesos y tareas de steward. Los mensajes enlazan con la lista de solicitudes o la tabla; con SMTP configurado llega una copia por correo. Jefes de proyecto y admins pueden «Solicitar descripciones de negocio» en cualquier tabla: el steward recibe un mensaje; sin steward se pide al propietario que asigne uno; sin propietario se pide a los admins.` },
      { icon: "send", title: "Solicitudes de acceso (productos de datos)", body: `Los esquemas de una base gold son productos de datos (p. ej. Sales › SALES_DE › GOLD › partners). Cada uno tiene un botón «Solicitar acceso» que abre el Marketplace con el producto preseleccionado.` },
      { icon: "tag", title: "Etiquetas Project y Use Case", body: `Tablas y productos de datos llevan las etiquetas «Project» y «Use Case» con uno o varios valores — fijadas en la página de la tabla o del producto por propietarios/stewards, o automáticamente desde un diseño. Son buscables, se exportan en CSV/OKF y las devuelve MCP.` },
      { icon: "layers", title: "Descubrir productos de datos (jefes de proyecto, admins)", body: `Una página con el estado de todos los productos de datos, filtrable por dominio, proyecto y caso de uso: terminados (esquemas en bases gold y diseños completados) y cada producto planificado o solicitado con su fase, estado exacto y de quién se espera respuesta — ordenados por dominio y tipo de hub. Las filas abren el esquema o la lista de solicitudes.` },
      { icon: "users", title: "Idioma", body: `La interfaz está disponible en inglés, alemán, polaco, español, francés e italiano — cámbiela con el selector junto a Cerrar sesión (o en la pantalla de inicio de sesión). La elección se guarda en su cuenta; las notificaciones le llegan en ese idioma.` },
      { icon: "layers", title: "Catálogos grandes", body: `Por encima de 5.000 atributos el catálogo carga de forma diferida: el árbol, las tablas y los paneles llegan de inmediato con contadores, y los atributos de una tabla se cargan al abrirla. Las exportaciones y la escritura de vuelta usan automáticamente el catálogo completo.` },
      { icon: "usercog", title: "Mi panel", body: `Tu vista personal: tus roles y el registro de persona correspondiente con tus dominios; todo lo pendiente de tu acción (aprobaciones y confirmaciones del flujo, solicitudes de acceso a tus productos, tareas de steward y mensajes no leídos); solicitudes y diseños que iniciaste con fase y siguiente paso; tus términos del glosario; y cada hub, base, esquema y tabla donde eres BPO, propietario o steward.` },
      { icon: "shield", title: "Permisos — quién puede cambiar qué", body: `Los roles de cuenta deciden si puedes iniciar sesión y editar; las responsabilidades deciden qué. Una persona puede tener varios roles — los permisos siguen al más alto (Admin › Data steward › Jefe de proyecto › Analista / Data Ingestion / Desarrollo › Invitado); los pasos del flujo se dirigen a todos los roles que tengas. Las responsabilidades son por persona: tu cuenta se empareja con el directorio de personas por correo (o nombre exacto).

• **Herencia**: propiedad y stewardship fluyen hacia abajo — hub (BPO) → dominio → base → esquema → tabla — y pueden sobrescribirse en cada nivel. Los tipos de hub no tienen propietario. Los dominios también se heredan.
• **Admins**: invitan usuarios, cambian la estructura, asignan BPO y propietarios, restauran el historial — todo.
• **Propietarios de datos**: asignan el steward en sus activos y por debajo; editan tablas y atributos como un steward.
• **Data stewards**: editan tablas y atributos de los que son steward efectivo, incl. crear tablas en sus esquemas.
• **Linaje**: admins o el propietario/steward de una de las dos tablas. **Glosario**: admins o cualquiera con al menos una responsabilidad.
• **Invitados** y los roles de flujo (jefe de proyecto, Data Ingestion, desarrollo): leen todo, usan el Marketplace y actúan en el flujo — sin editar el catálogo.
• **Agentes**: cuentas técnicas para clientes MCP, sin rol de gobernanza, creadas y eliminadas solo por admins; sus claves (alcance lectura o escritura) son la credencial para POST /mcp.

Los botones que no puedes usar están ocultos; el servidor aplica las mismas reglas en cada guardado.` },
      { icon: "bot", title: "Servidor MCP para agentes de IA", body: `El catálogo es un servidor Model Context Protocol (Streamable HTTP, JSON-RPC 2.0) en POST /mcp. Los agentes — Claude, frameworks de agentes, asistentes IDE — leen, buscan y cambian el catálogo con las mismas reglas que la UI; la gestión de usuarios no está expuesta. Cada cambio de un agente se audita con su nombre.

**Conexión.** URL https://<servidor>/mcp con la cabecera Authorization: Bearer <clave>; la clave es el MCP_TOKEN estático o una clave de agente emitida en la gestión de usuarios. Los clientes que solo hablan stdio usan npx mcp-remote como puente.

**Métodos.** initialize, ping, tools/list, tools/call, resources/list, resources/read. Ejemplo:
${EX_CALL}
**Las referencias** son rutas: base, base.esquema, base.esquema.tabla, base.esquema.tabla.atributo (sin distinguir mayúsculas).

**Herramientas.** Lectura: get_overview, list_hubs, list_databases, list_schemas, list_tables, get_table, list_data_products, get_lineage, search_catalog, get_audit. Escritura: create/update/delete de hubs, bases, esquemas, tablas y atributos, add/remove lineage, map/unmap lineage attributes, export_okf. Las claves de lectura se rechazan en herramientas de escritura.` },
      { icon: "json", title: "OKF vía MCP — cómo leen los agentes el catálogo", body: `Todo el catálogo se expone como paquete Open Knowledge Format de dos formas:

• **Recursos** (recomendado para leer): resources/list devuelve cada archivo de concepto como okf://<ruta>; resources/read devuelve su Markdown. Empieza en okf://index.md y sigue los enlaces hacia abajo — el agente lee solo lo que necesita.
${EX_READ}
• **Herramienta export_okf**: hub, database, schema, table opcionales limitan el paquete a un subárbol; format files (por defecto) o zip_base64.
${EX_OKF}
Un archivo de concepto tiene frontmatter YAML (type, title, id, path, hub, data_hub, medallion_layer, data_product, steward, tags, provenance) y Markdown con descripción, definición de negocio, gobernanza, tabla de atributos y secciones de linaje. Es el mismo paquete que descarga Exportar → Exportar OKF.` },
      { icon: "server", title: "Cargar fuentes de datos genéricas (admins)", body: `Los admins inspeccionan sistemas fuente en vivo: archivos de base de datos DuckDB en el servidor del catálogo (controlador nativo, solo lectura, con textos COMMENT ON y claves primarias), MySQL/MariaDB, PostgreSQL, IBM DB2 y SAP HANA vía SQLAlchemy (o cualquier dialecto vía URL SQLAlchemy), Microsoft SQL Server (pymssql), Oracle (oracledb thin) y Snowflake, archivos de data lake con DuckDB (Parquet/CSV/JSON/Delta/Iceberg — locales, S3/MinIO, Azure Data Lake; cada ruta o glob se convierte en una tabla de tipo FILE), SAP SuccessFactors y cualquier servicio OData v2/v4 vía $metadata (tipos de entidad → tablas, claves → claves primarias, etiquetas SAP → descripciones), Kafka Schema Registry (último esquema Avro/JSON Schema/Protobuf por subject → topics como tablas de tipo TOPIC, registros anidados como atributos con punto, esquema de clave como claves primarias key.*), cualquier otro sistema vía el conector JDBC genérico e Informatica Data Catalog vía su Catalog Search API. Las bases cargadas se colocan en el tipo SOURCE y no tienen escritura de vuelta. Las fuentes en paquete van a un hub a elegir y traen linaje: Power BI (Scanner API de administración — área de trabajo → base, conjunto de datos → esquema, tablas con columnas y medidas, informes como objetos de tipo REPORT en el esquema «Reports» con linaje tabla del conjunto → informe), dbt (modelos/seeds/snapshots/fuentes → tablas, columnas documentadas con tipos de catalog.json, tests not_null/unique → nulabilidad y claves, depends_on → linaje; las tablas existentes se enriquecen en vez de duplicarse) y archivos Open Data Contract Standard (v3 schema/properties o v2 dataset/columns: classification → sensibilidad, businessName → término de negocio, primaryKey/required → clave y nulabilidad; contrato, estado, dominio, producto de datos y equipo en la definición de negocio). Desde v1.60 los conectores de API (OData/SuccessFactors, Kafka Schema Registry, Power BI, Informatica) se ejecutan dentro del propio servidor del catálogo; solo DuckDB, archivos lake, dialectos SQL y JDBC necesitan el servicio inspector opcional en Python. En instalaciones sin él (por ejemplo Databricks Apps) esas entradas se ocultan y el diálogo indica la alternativa: registrar las bases en Unity Catalog (Lakehouse Federation) y cargarlas con la sincronización de Unity Catalog.` },
      { icon: "shield", title: "Stewardship: certificación, revisiones, atestación de propiedad", body: `En la pestaña Governance de una tabla el propietario o steward responsable puede **avalar** la tabla (endorsed — fiable, revisada; cuenta como revisión), **deprecarla** con una tabla sucesora opcional y un motivo (los consumidores ven la insignia y la sucesora en la tabla, en las tarjetas del esquema y en el panel), quitar la certificación, **marcarla como revisada** y fijar un **ciclo de revisión** (90/180/365 días). Los propietarios **confirman la propiedad** de tablas, esquemas, bases y dominios donde están asignados explícitamente; la política (Resumen de gobernanza, admins) define la frecuencia — por defecto cada 180 días. Las revisiones y atestaciones pendientes o vencidas aparecen en Mi panel › Tareas de stewardship con acciones de un clic; una vez al día los responsables reciben un recordatorio en la app (correo si hay SMTP), como máximo cada 7 días por objeto. Solo el propietario atesta; los stewards revisan y certifican. Los agentes MCP usan certify_table, review_table y list_stewardship_tasks.` },
      { icon: "server", title: "Copias de seguridad y trabajos (admins)", body: `Admin › Copias de seguridad y trabajos escribe a diario a la hora configurada (y bajo demanda) un volcado comprimido del catálogo en el servidor — más un volcado SQL completo de toda la base cuando mysqldump está instalado; la retención es configurable. **Verificar** ejecuta un simulacro de restauración: se relee el archivo, se comprueban estructura e integridad referencial y se comparan los recuentos con el catálogo en vivo. **Restaurar** aplica una copia mediante el trabajo de restauración habitual; las descargas entregan los archivos. La página también lista los últimos trabajos en segundo plano (importaciones, restauraciones, copias) con su resultado; la lista se guarda en la base y sobrevive a reinicios — un trabajo en curso durante un reinicio se muestra como interrumpido.` },
      { icon: "message", title: "Colaboración: discusión, preguntas, valoraciones, uso", body: `Cada tabla tiene una pestaña **Discusión** (los productos de datos muestran la discusión bajo sus tablas): cualquier usuario conectado puede comentar, hacer **preguntas** y responderlas. Una pregunta avisa al data steward y al propietario efectivos (en la app, e-mail con SMTP) en su idioma; una respuesta avisa a quien preguntó; quien preguntó, los stewards y los admins marcan la pregunta como **resuelta**. Las preguntas abiertas dirigidas a usted — y las suyas — aparecen en Mi panel › Preguntas. Tablas y productos de datos llevan una **valoración por estrellas** (1–5, un voto por persona, media en la cabecera). El catálogo también registra el **uso**: vistas (una por persona y objeto cada diez minutos), términos de búsqueda y exportaciones. La línea de uso de una tabla está en sus pestañas Gobernanza y Discusión; el panel Uso del panel principal muestra las tablas más vistas, los términos más buscados y las mejor valoradas para 7 a 365 días. Los agentes MCP usan get_discussion, list_open_questions y add_comment; get_table incluye valoración, preguntas abiertas y uso.` },
      { icon: "key", title: "OAuth 2.1 para clientes MCP", body: `Además de las claves de agente, los clientes MCP (Claude, asistentes de IDE, frameworks de agentes) pueden conectarse **como usted** mediante OAuth 2.1: el cliente descubre /.well-known/oauth-protected-resource y /.well-known/oauth-authorization-server, se registra dinámicamente (RFC 7591), le envía a una página de consentimiento (inicie sesión antes si hace falta) y recibe un token de acceso con PKCE (S256, obligatorio). Los tokens son opacos, caducan en una hora y se renuevan con tokens de refresco rotativos (30 días); el ámbito catalog:write solo se concede a Admins y Data Stewards — el resto recibe catalog:read. Cada cambio se audita a su nombre. El icono de llave › **Aplicaciones MCP conectadas** lista sus conexiones y permite desconectarlas (todos sus tokens caducan al instante); los Admins ven todas las conexiones en Usuarios. Cada credencial — token OAuth, clave de agente o token estático — tiene límite de tasa (por defecto 300 solicitudes y 60 llamadas de escritura por minuto; HTTP 429 con Retry-After).` },
      { icon: "key", title: "Identidad: SSO forzado, asignación grupo → rol, inicio de sesión por proxy", body: `Los admins pueden **forzar el SSO**: todos inician sesión mediante Entra ID y la contraseña queda solo para las **cuentas de emergencia** listadas (su cuenta se añade si la lista está vacía) — la pantalla de inicio muestra entonces el botón de Microsoft y un pequeño enlace «Inicio de sesión de emergencia». La **asignación grupo → rol** (Admin › Usuarios) deriva los roles del catálogo de los grupos del proveedor de identidad: el claim groups de Entra (ids o nombres) y roles de app, o — en modo cabecera — la cabecera de grupos del proxy o los grupos de la cuenta Databricks. Las reglas deciden los roles de las cuentas nuevas; con «los roles siguen a los grupos» se reaplican en cada inicio de sesión y los usuarios sin coincidencia reciben los roles por defecto o se les deniega. El último admin nunca se degrada. En **modo cabecera** (AUTH_MODE=header, p. ej. como Databricks App o tras oauth2-proxy) el catálogo confía en las cabeceras de identidad del proxy, crea cuentas al primer contacto (AUTH_BOOTSTRAP_ADMINS son admins) y no muestra formulario; una cabecera con secreto compartido protege el puerto de Node. Las claves y tokens MCP no se ven afectados.` },
      { icon: "server", title: "Operación: motores de base de datos, almacenamiento de copias, health, planificador externo", body: `El servidor funciona con **MariaDB (por defecto) o PostgreSQL / Databricks Lakebase** (DB_DRIVER=postgres; el mismo SQL en el código, DDL traducido, búsqueda de texto completo tsvector, copias con pg_dump; las credenciales de Lakebase se obtienen por conexión con DB_PASSWORD_PROVIDER=databricks). Las copias van a un **directorio local, un bucket compatible con S3, un contenedor Azure Blob o un volumen de Unity Catalog** (BACKUP_STORAGE=local|s3|azure|databricks); restauración, simulacros y descargas leen del mismo almacenamiento. **GET /healthz** informa la disponibilidad (base de datos, versión del catálogo, trabajos activos, memoria) para monitorización y health checks. Las tareas programadas — copia, recordatorios de stewardship, purga de uso, sincronización de Unity Catalog — se ejecutan bajo demanda con **POST /admin/tasks/<name>/run** (sesión de admin o bearer TASKS_TOKEN); con SCHEDULER=external los temporizadores internos se apagan y un planificador de plataforma (cron, Databricks Job) los dirige. SIGTERM apaga el servicio limpiamente en 15 segundos: los trabajos en curso se marcan interrumpidos y el pool se cierra. Exportación del dump, copias, exportaciones CSV/OKF e importación CSV transmiten los atributos tabla por tabla, así que ni 400.000 atributos están en memoria a la vez.` },
      { icon: "upload", title: "Sincronización programada de Unity Catalog", body: `Admin › Copias y trabajos › **Sincronización programada**: un perfil nombra un workspace de Databricks, un catálogo de Unity Catalog, el tipo de data hub / data hub / capa de destino, la autenticación (token personal, service principal o la identidad de la app en Databricks Apps), un horario (manual, cada hora, diario a una hora) y un modo. **Solo informe** registra la desviación — esquemas, tablas y columnas nuevas, tablas y columnas eliminadas, tipos de columna cambiados — y avisa a los stewards y propietarios responsables en su idioma (admins cuando nadie es responsable); **Aplicar** además importa los objetos nuevos, actualiza los tipos de columna y, si está activado, elimina tablas y columnas desaparecidas de Unity Catalog (linaje opcional). Cada ejecución se audita; el último resultado con ejemplos se muestra en el perfil. «Probar conexión» cuenta esquemas, tablas y columnas sin tocar el catálogo; «Ejecutar ahora» ignora el horario. **Escritura de vuelta (v1.64):** un perfil también puede escribir los metadatos del catálogo en Unity Catalog tras cada ejecución o bajo demanda — descripciones como comentarios, propietario / steward / dominio / sensibilidad / clasificación como etiquetas UC, hub / capa / país como propiedades del catálogo; solo diferencias, nada se crea ni se elimina, sin navegador. Actívalo en el perfil, indica el ID del SQL warehouse para etiquetas y comentarios de columnas, previsualiza con el botón de la nube, ejecuta con «Escribir de vuelta»; el resultado aparece bajo el perfil y en la auditoría. Sin ID de warehouse, los cambios que necesitan SQL (comentarios de columnas, propiedades de tablas, etiquetas) se cuentan como omitidos — los comentarios y las propiedades del catálogo se escriben igualmente y la ejecución no falla. **v1.66:** el ID del SQL warehouse es un ajuste del perfil para ambas direcciones — al importar con «Importar etiquetas de gobierno» se leen las etiquetas (sensibilidad, clasificación, propietario / steward / dominio) y en la escritura de vuelta se escriben etiquetas y comentarios de columnas. La importación puntual del menú Importar usa el mismo mecanismo y puede guardarse como perfil.` },
      { icon: "boxes", title: "Panel", body: `La página de inicio muestra KPI del catálogo: tipos de hub y objetos, productos de datos, propietarios y stewards distintos, y la cobertura de gobernanza — porcentaje de bases con propietario, tablas con steward y productos con propietario y steward. Desde v1.66 los KPI de cobertura de atributos (tablas y atributos con descripción, atributos con sensibilidad y término de negocio) se calculan en el servidor (/api/stats), por lo que son exactos también en catálogos grandes de carga diferida.` },
      { icon: "shield", adminOnly: true, title: "Menú Admin (solo admins)", body: `• **Usuarios** — invitar personas por correo con roles (selección múltiple; sin SMTP se muestra el enlace para copiar), editar nombre, correo y roles, ver estado 2FA/Entra, eliminar cuentas; crear agentes por nombre con clave MCP y alcance lectura/escritura; configurar el inicio de sesión con Entra ID. El último admin no puede degradarse ni eliminarse. Los enlaces de invitación se muestran una vez (los tokens se guardan con hash) — *Renovar* emite un nuevo enlace, *Retirar* cancela la invitación. El botón de flecha circular junto a una cuenta con contraseña emite un **enlace de restablecimiento de contraseña** (24 horas, un solo uso, por correo si hay SMTP).
• **Resumen de gobernanza** — asignar el BPO por hub y propietarios/stewards por dominio, ver quién tiene los roles de flujo, mantener el directorio de personas.
• **Registro de auditoría** — el historial completo de cambios del catálogo.
• **Volcado / Restaurar** — descargar el catálogo completo como JSON (copia) y sustituirlo desde un volcado; las restauraciones se auditan, las cuentas no se tocan.
• **Exportar términos del glosario** — todos los términos como JSON (adjuntos como referencias).` },
    ],
  },
  fr: helpFr({ EX_CALL, EX_READ, EX_OKF }),
  it: helpIt({ EX_CALL, EX_READ, EX_OKF }),
};
